To model solar and stellar oscillations, we consider the damped time-harmonic \emph{Galbrun's equation}: Find $\mathbf{u} : \mathcal{O} \to \mathbb{C}^d$ such that 
\begin{subequations}\label{eq:Galbrun}
\begin{align}
   \begin{aligned}
      -\rho(\omega+i\partial_{\mathbf{b}}+i\Omega\times)^2\mathbf{u} 
      &- \nabla\left(\rho c_s^2\operatorname{div} \mathbf{u}\right)
      + (\operatorname{div} \mathbf{u}) \nabla p -\nabla(\nabla p\cdot \mathbf{u})\\
      & + (\mathrm{Hess}(p)-\rho\mathrm{Hess}(\phi))\mathbf{u} 
      + \gamma \rho (-i \omega) \mathbf{u}
      = \mathbf{f} \quad \text{ in } \mathcal{O},
   \end{aligned}& \\
   \boldsymbol{\nu} \cdot \mathbf{u} = 0 \quad \text{ on } \partial &\mathcal{O},
\end{align}
\end{subequations}
where $\mathcal{O} \subset \mathbb{R}^d$, $d = 2,3$, is a bounded Lipschitz domain.

\begin{align}
   \begin{aligned}
      -\rho(\omega+i\partial_{\mathbf{b}}+i\Omega\times)^2\mathbf{u} 
      &- \nabla\left(\rho c_s^2\operatorname{div} \mathbf{u}\right)
      + (\operatorname{div} \mathbf{u}) \nabla p -\nabla(\nabla p\cdot \mathbf{u})\\
      & + (\mathrm{Hess}(p)-\rho\mathrm{Hess}(\phi))\mathbf{u} 
      + \gamma \rho (-i \omega) \mathbf{u}
      = \mathbf{f} \quad \text{ in } \mathcal{O},
   \end{aligned}& \\
   \boldsymbol{\nu} \cdot \mathbf{u} = 0 \quad \text{ on } \partial &\mathcal{O},
\end{align}

\begin{equation} \label{eq:coercivity:C}
\inf_{u \in X \setminus \{ 0 \}} \frac{\operatorname{Re}( \xi \langle Au, u \rangle_X)}{\Vert u \Vert^2_X} > 0 .
\end{equation}

\begin{equation*}
   \inf_{u \in X  \setminus \{ 0 \}} \sup_{v \in X  \setminus \{ 0 \}} \frac{\vert \langle Au, v \rangle_X \vert}{\Vert u \Vert_X \Vert v \Vert_X} > 0.
\end{equation*}

\label{thm:weakTcompatibility}
   Assume that there exists a constant $C>0$, sequences $\seq{A}$, $\seq{T}$, $\seq{B}$, $\seq{K}$ and $B,T \in L(X)$ such that for each $n \in \mathbb{N}$ it holds that $A_n,T_n,B_n,K_n \in L(X_n)$, $\Vert T_n \Vert_{L(X_n)}$, $\Vert T_n^{-1} \Vert_{L(X_n)}$, $\Vert B_n \Vert_{L(X_n)}$, $\Vert B_n^{-1} \Vert_{L(X_n)} \le C$, $B$ is bijective, $\seq{K}$ is \hyperlink{compactop}{compact}~and 
   \begin{equation*}
      \lim_{n \rightarrow \infty} \Vert T_n p_n u - p_n T u \Vert_{X_n} = 0, \qquad \lim_{n \rightarrow \infty} \Vert B_n p_n u - p_n B u \Vert_{X_n} = 0, \qquad \forall u \in X,
   \end{equation*} 
   \begin{equation*}
      A_n T_n = B_n + K_n. 
   \end{equation*}
   Then the sequence $\seq{A}$ is \hyperlink{regular}{regular}.

\begin{equation*}
      \lim_{n \rightarrow \infty} \Vert T_n p_n u - p_n T u \Vert_{X_n} = 0, \qquad \lim_{n \rightarrow \infty} \Vert B_n p_n u - p_n B u \Vert_{X_n} = 0, \qquad \forall u \in X,
   \end{equation*}

\begin{equation*}
      A_n T_n = B_n + K_n. 
   \end{equation*}

Furthermore, we define the space 
\begin{equation}\label{eq:defH1nu0}
   {\mathbf H}^1_{\boldsymbol{\nu} 0} \coloneqq \{ \mathbf{v} \in {\mathbf H}^1 : \mathbf{v} \cdot \boldsymbol{\nu} = 0 \text{ on } \partial \mathcal{O} \}.   
\end{equation}

\begin{equation}\label{eq:defH1nu0}
   {\mathbf H}^1_{\boldsymbol{\nu} 0} \coloneqq \{ \mathbf{v} \in {\mathbf H}^1 : \mathbf{v} \cdot \boldsymbol{\nu} = 0 \text{ on } \partial \mathcal{O} \}.   
\end{equation}

\begin{equation}\label{eq:CoeffsBounded}
   \underline{c_s} \le c_s(\bm{x}) \le \overline{c_s}, \quad \underline{\rho} \le \rho(\bm{x}) \le \overline{\rho}, \quad \underline{\gamma} \le \gamma(\bm{x}) \le \overline{\gamma} \quad \text{ for all } \bm{x} \in \mathcal{O}, 
\end{equation}

\begin{equation}
      \mathbb{X} \coloneqq \{ \mathbf{u} \in \mathbf{L}^2 : \operatorname{div} \mathbf{u} \in L^2, \partial_{\mathbf{b}} \mathbf{u} \in \mathbf{L}^2, \boldsymbol{\nu} \cdot \mathbf{u} = 0 \text{ on } \partial \mathcal{O} \}. 
\end{equation}

\begin{equation*}
   \inner{\mathbf{u}, \mathbf{u}'}_{\mathbb{X}} \coloneqq \innercsr{\operatorname{div} \mathbf{u}, \operatorname{div} \mathbf{u}'} + \inner{\mathbf{u}, \mathbf{u}'} + \innerr{\partial_{\mathbf{b}} \mathbf{u}, \partial_{\mathbf{b}} \mathbf{u}'}
\end{equation*}

\begin{align}
      a^{\operatorname{div}}(\mathbf{u},\mathbf{u}') &\coloneqq \inner{c_s^2 \rho \operatorname{div} \mathbf{u},\operatorname{div} \mathbf{u}'}_{L^2} + \inner{\operatorname{div} \mathbf{u}, \nabla p \cdot \mathbf{u}'}_{L^2} + \inner{\nabla p \cdot \mathbf{u}, \operatorname{div} \mathbf{u}'}_{L^2}, \\
      a^{\partial_{\mathbf{b}}}(\mathbf{u},\mathbf{u}') &\coloneqq \inner{\rho (\omega+i\partial_{\mathbf{b}}+i\Omega\times) \mathbf{u}, (\omega+i\partial_{\mathbf{b}}+i\Omega\times) \mathbf{u}'}_{\mathbf{L}^2}, \\
      a^{r}(\mathbf{u},\mathbf{u}') &\coloneqq \inner{(\mathrm{Hess}(p) - \rho \mathrm{Hess}(\phi)) \mathbf{u}, \mathbf{u}'}_{\mathbf{L}^2} - i \omega \inner{\gamma \rho \mathbf{u}, \mathbf{u}'}_{\mathbf{L}^2}.
   \end{align}

we define the sesquilinear form $a \colon \mathbb{X} \times \mathbb{X} \to \mathbb{C}$ by
\begin{equation}\label{eq:a}
      a(\mathbf{u},\mathbf{u}') \coloneqq a^{\operatorname{div}}(\mathbf{u},\mathbf{u}') - a^{\partial_{\mathbf{b}}}(\mathbf{u},\mathbf{u}') + a^{r}(\mathbf{u},\mathbf{u}')
