      a^{(r-\mathbf{q}\cdot)} (\mathbf{u},\mathbf{u}') &\coloneqq \inner{(\mathrm{Hess}(p) - \rho \mathrm{Hess}(\phi)-c_s^2\rho \mathbf{q} \otimes \mathbf{q}) \mathbf{u}, \mathbf{u}'} - i \omega \inner{\gamma \rho \mathbf{u}, \mathbf{u}'}, 
