      \mathbb{X}_{\mathcal{T}_n} \coloneqq \mathbb{BDM}_{k} \coloneqq \{ \mathbf{u}_{\tau} \in [\mathbb{P}^k(\mathcal{T}_n)]^d : \jump{\mathbf{u}_{\tau} \cdot \boldsymbol{\nu}}_{F} = 0 \ \forall F \in \mathcal{F}_n \} \subset H(\operatorname{div}, \mathcal{O}),
   \end{equation*}
   where we recall that $\jump{\cdot}_{F}$, $F \in \mathcal{F}_n$, denotes the usual DG-jump operator. To obtain an $H(\operatorname{div})$-conforming HDG discretization \cite{LS16}, we set $\mathbb{X}_{\mathcal{F}_n}$ to be the space of tangential polynomials on the skeleton $\mathcal{F}_n$:
   \begin{equation*}
      \mathbb{X}_{\mathcal{F}_n} \coloneqq \mathbb{P}^{k,\text{tang}}(\mathcal{F}_n) =  \{ \mathbf{u}_F \in [\mathbb{P}^k(\mathcal{F}_n)]^d : P_{\boldsymbol{\nu}} \mathbf{u}_F = 0 \}.  
   \end{equation*}
   For these choices, we redefine the HDG-jump operators as $\hdgjump{\mathbf{u}_n} \coloneqq P_{\boldsymbol{\nu}}^{\perp} \mathbf{u}_{\tau} - \mathbf{u}_F$ such that $\hdgjump{\mathbf{u}_n}_{\boldsymbol{\nu}} = 0$.
   Consequently, we obtain that $R^l \mathbf{u}_n = 0$ for all $\mathbf{u}_n \in \mathbb{X}_n$ and therefore we have that $\operatorname{div}_{\boldsymbol{\nu}}^n = \operatorname{div}$ and $s_n(\cdot,\cdot) = 0$.

   To optimize the computational efficiency, we can use relaxed $H(\operatorname{div})$-conforming spaces as introduced in \cite{LLS18,LLS19}. We define 
   \begin{equation*}
      \mathbb{BDM}_{k}^{-} \coloneqq \{ \mathbf{u}_\tau \in [\mathbb{P}^k(\mathcal{T}_n)]^d : \Pi_F^{k-1} \jump{\mathbf{u}_\tau \cdot \boldsymbol{\nu}}_F = 0 \ \forall F \in \mathcal{F}_n \},
   \end{equation*}
   where $\Pi_F^{k-1}$ is the $L^2$-projection onto $[\mathcal{P}^{k-1}(F)]^d$. While functions in $\mathbb{BDM}_{k}^{-}$ are not normal-continuous in the highest order, this relaxation reduces the number of coupling degrees of freedoms improving the sparsity pattern of the system matrices. The choice of $\mathbb{X}_{\mathcal{T}_n} = \mathbb{BDM}_{k}^{-}$ and $\mathbb{X}_{\mathcal{F}_n} = \mathbb{P}^{k,\text{tang}}(\mathcal{F}_n)$ still yields $R^l \mathbf{u}_n = 0$ if the lifting degree satisfies $l \le k-1$.

\begin{equation*}
      \mathbb{X}_{\mathcal{T}_n} \coloneqq \mathbb{BDM}_{k} \coloneqq \{ \mathbf{u}_{\tau} \in [\mathbb{P}^k(\mathcal{T}_n)]^d : \jump{\mathbf{u}_{\tau} \cdot \boldsymbol{\nu}}_{F} = 0 \ \forall F \in \mathcal{F}_n \} \subset H(\operatorname{div}, \mathcal{O}),
   \end{equation*}

\begin{equation*}
      \mathbb{X}_{\mathcal{F}_n} \coloneqq \mathbb{P}^{k,\text{tang}}(\mathcal{F}_n) =  \{ \mathbf{u}_F \in [\mathbb{P}^k(\mathcal{F}_n)]^d : P_{\boldsymbol{\nu}} \mathbf{u}_F = 0 \}.  
   \end{equation*}

\begin{equation*}
      \mathbb{BDM}_{k}^{-} \coloneqq \{ \mathbf{u}_\tau \in [\mathbb{P}^k(\mathcal{T}_n)]^d : \Pi_F^{k-1} \jump{\mathbf{u}_\tau \cdot \boldsymbol{\nu}}_F = 0 \ \forall F \in \mathcal{F}_n \},
   \end{equation*}

\begin{equation}\label{eq:def:pn}
   \inner{p_n \mathbf{u}, \mathbf{u}_n'}_{\mathbb{X}_n} \! = \! \innercsr{\operatorname{div} \mathbf{u}, \operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{u}_n'}_{L^2} + \inner{\mathbf{u}, \mathbf{u}_{\tau}'}_{\mathbf{L}^2} + \innerr{\partial_{\mathbf{b}} \mathbf{u}, \mathbf{D}_{\mathbf{b}}^n \mathbf{u}_n'}_{\mathbf{L}^2} \! \!
   \quad \forall \mathbf{u}_n' \in \mathbb{X}_n.
\end{equation}

\begin{equation}\label{eq:GalerkinOrthogonality}
   \begin{aligned}
      0 = &\innercsr{(\operatorname{div} \mathbf{u} - \operatorname{div}_{\boldsymbol{\nu}}^n p_n \mathbf{u}), \operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{u}_n'}_{\mathcal{T}_n} + \inner{\mathbf{u} - \PVol{p_n \mathbf{u}}, \mathbf{u}_n'}_{\mathcal{T}_n} \\
      &+ \innerr{(\partial_{\mathbf{b}} \mathbf{u} - \mathbf{D}_{\mathbf{b}}^n p_n \mathbf{u}), \mathbf{D}_{\mathbf{b}}^n \mathbf{u}_n'}_{\mathcal{T}_n} - \innercsr{\mathfrak{h}^{-1} \hdgjump{p_n \mathbf{u}}_{\boldsymbol{\nu}}, \jump{\mathbf{u}_n'}_{\boldsymbol{\nu}}}_{\partial \mathcal{T}_n}
   \end{aligned}
\end{equation}

To circumvent this issue, we introduce a distance function $d_n : \mathbb{X} \times \mathbb{X}_n \to \mathbb{R}^{+}_0$, 
\begin{equation}
   \begin{aligned}
      d_n(\mathbf{u},\mathbf{u}_n')^2 \coloneqq &\Vert (c_s^2 \rho)^{1/2}(\operatorname{div} \mathbf{u} - \operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{u}_n) \Vert_{L^2}^2 + \Vert \mathbf{u} - \mathbf{u}_{\tau} \Vert_{\mathbf{L}^2}^2 \\
      &+ \Vert \rho^{1/2} (\partial_{\mathbf{b}} \mathbf{u} - \mathbf{D}_{\mathbf{b}}^n \mathbf{u}_n) \Vert_{\mathbf{L}^2}^2 + \jnorm{\mathbf{u}_h}{2}, 
   \end{aligned}
\end{equation}
where we define the following jump norm on $\mathbb{X}_n$:
\begin{equation}\label{eq:def:jumpNorm}
   \jnorm{\mathbf{u}_h}{2} \coloneqq \Vert (c_s^2 \rho)^{1/2} \mathfrak{h}^{-1/2} \hdgjump{\mathbf{u}_n}_{\boldsymbol{\nu}} \Vert_{L^2(\partial \mathcal{T}_n)}^2. 
\end{equation}

\begin{equation}
   \begin{aligned}
      d_n(\mathbf{u},\mathbf{u}_n')^2 \coloneqq &\Vert (c_s^2 \rho)^{1/2}(\operatorname{div} \mathbf{u} - \operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{u}_n) \Vert_{L^2}^2 + \Vert \mathbf{u} - \mathbf{u}_{\tau} \Vert_{\mathbf{L}^2}^2 \\
      &+ \Vert \rho^{1/2} (\partial_{\mathbf{b}} \mathbf{u} - \mathbf{D}_{\mathbf{b}}^n \mathbf{u}_n) \Vert_{\mathbf{L}^2}^2 + \jnorm{\mathbf{u}_h}{2}, 
   \end{aligned}
\end{equation}

\begin{equation}\label{eq:def:jumpNorm}
   \jnorm{\mathbf{u}_h}{2} \coloneqq \Vert (c_s^2 \rho)^{1/2} \mathfrak{h}^{-1/2} \hdgjump{\mathbf{u}_n}_{\boldsymbol{\nu}} \Vert_{L^2(\partial \mathcal{T}_n)}^2. 
\end{equation}

\begin{equation}\label{eq:dn:triangle}
   d_n(\mathbf{u},\mathbf{u}_n) \le d_n(\tilde{\mathbf{u}},\mathbf{u}_n) + \Vert \tilde{\mathbf{u}} - \mathbf{u} \Vert_{\mathbb{X}}, \quad d_n(\mathbf{u},\mathbf{u}_n) \le d_n(\mathbf{u},\tilde{\mathbf{u}}_n) + \Vert \tilde{\mathbf{u}}_n - \mathbf{u}_n \Vert_{\mathbb{X}_n}, 
\end{equation}

\label{lem:pinXd:properties}
   Let $\mathbf{u} \in {\mathbf H}^{1+s}$, $0 \le s \le k$, and $\underline{\tilde{\pi}}_n^d$ be defined by \eqref{eq:def:pinXd}. Then
   \begin{equation}\label{eq:pinXd:jumps}
      \hdgjump{\underline{\tilde{\pi}}_n^d \mathbf{u}}_{\boldsymbol{\nu}} = 0 \qquad \text{and} \qquad \hdgjump{\underline{\tilde{\pi}}_n^d \mathbf{u}} = P_{\boldsymbol{\nu}}^{\perp}(\pi_n^d \mathbf{u} - \pi_n^{\mathcal{F}_n}\mathbf{u}).
   \end{equation}
   Furthermore, there exists a constant $C > 0$ such that 
   \begin{equation}\label{eq:pinXd:boundedness}
	   \Vert \underline{\mathbf{u}} - \underline{\tilde{\pi}}_n^d \mathbf{u} \Vert_{\mathbb{X}_n} \le C h^s_n \Vert \mathbf{u} \Vert_{{\mathbf H}^{1+s}},
   \end{equation}
   where $\underline{\mathbf{u}} = (\mathbf{u}, \mathrm{tr} \mathbf{u})$.

\begin{equation}\label{eq:pinXd:jumps}
      \hdgjump{\underline{\tilde{\pi}}_n^d \mathbf{u}}_{\boldsymbol{\nu}} = 0 \qquad \text{and} \qquad \hdgjump{\underline{\tilde{\pi}}_n^d \mathbf{u}} = P_{\boldsymbol{\nu}}^{\perp}(\pi_n^d \mathbf{u} - \pi_n^{\mathcal{F}_n}\mathbf{u}).
   \end{equation}

\begin{equation}\label{eq:pinXd:boundedness}
	   \Vert \underline{\mathbf{u}} - \underline{\tilde{\pi}}_n^d \mathbf{u} \Vert_{\mathbb{X}_n} \le C h^s_n \Vert \mathbf{u} \Vert_{{\mathbf H}^{1+s}},
   \end{equation}

   The properties \eqref{eq:pinXd:jumps} hold by definition of $\underline{\tilde{\pi}}_n^d$. Since $\hdgjump{\underline{\tilde{\pi}}_n^d \mathbf{u}}_{\boldsymbol{\nu}} = 0$, it follows that $R^l \underline{\tilde{\pi}}_n^d \mathbf{u} = 0$ and therefore by definition of the discrete divergence operator $\operatorname{div}_{\boldsymbol{\nu}}^n$, we have that $\operatorname{div}_{\boldsymbol{\nu}}^n \underline{\tilde{\pi}}_n^d \mathbf{u} = \operatorname{div} \PVol{\underline{\tilde{\pi}}_n^d \mathbf{u}}$. The triangle inequality yields that 
   \begin{equation*}
      \Vert \underline{\mathbf{u}} - \underline{\tilde{\pi}}_n^d \mathbf{u} \Vert_{\mathbb{X}_n} \le \Vert \mathbf{u} - \PVol{\underline{\tilde{\pi}}_n^d \mathbf{u}} \Vert_{\mathbb{X}(\mathcal{T}_n)} + \Vert \rho^{1/2} \mathbf{R}^{\!l} (\underline{\mathbf{u}} -\underline{\tilde{\pi}}_n^d \mathbf{u}) \Vert_{\mathcal{T}_n}. 
   \end{equation*}
   For the first term, the commutation property $\operatorname{div} \pi_n^d = \pi_n^l \operatorname{div}$ and the approximation properties of $\pi_n^d$ and $\pi_n^l$ imply that $\Vert \mathbf{u} - \! \PVol{\underline{\tilde{\pi}}_n^d \mathbf{u}} \! \Vert_{\mathbb{X}(\mathcal{T}_n)} \! \lesssim \! h^s_n \Vert \mathbf{u} \Vert_{{\mathbf H}^{1+s}}$. 

   For the second term, we calculate with \eqref{eq:liftingBoundedness} and $\hdgjump{\underline{\mathbf{u}}} = 0$ that 
   \begin{equation}\label{eq:pinXd:RBoundedness}
      \begin{aligned}
         \Vert \rho^{1/2} \mathbf{R}^{\!l} (\underline{\mathbf{u}} - \underline{\tilde{\pi}}_n^d \mathbf{u}) \Vert_{\mathcal{T}_n} &\lesssim \Vert \rho^{1/2} \mathfrak{h}^{-1/2} \hdgjump{\underline{\tilde{\pi}}_n^d \mathbf{u}}_{\mathbf{b}} \Vert_{\mathbf{L}^2(\partial \mathcal{T}_n)} \\
		   &\lesssim \Vert \rho^{1/2} \mathfrak{h}^{-1/2} (\mathbf{b} \cdot \boldsymbol{\nu}) P_{\boldsymbol{\nu}}^{\perp}(\pi_n^d \mathbf{u} - \pi_n^{\mathcal{F}_n}\mathbf{u}) \Vert_{\mathbf{L}^2(\partial \mathcal{T}_n)}\\
		   &\lesssim \Vert \rho^{1/2} \mathfrak{h}^{-1/2} (\mathbf{b} \cdot \boldsymbol{\nu})(\pi_n^d \mathbf{u} - \mathbf{u}) \Vert_{\mathbf{L}^2(\partial \mathcal{T}_n)} \\
         &\quad + \Vert \rho^{1/2} \mathfrak{h}^{-1/2} (\mathbf{b} \cdot \boldsymbol{\nu})(\pi_n^{\mathcal{F}_n} \mathbf{u} - \mathbf{u}) \Vert_{\mathbf{L}^2(\partial \mathcal{T}_n)}\\
         &\lesssim h^s_n \Vert \mathbf{u} \Vert_{{\mathbf H}^{1+s}},
      \end{aligned}
   \end{equation}
   where we use the definition of $\underline{\tilde{\pi}}_n^d$ in the second line, the boundedness of $P_{\boldsymbol{\nu}}^{\perp}$ in the third and the approximation properties of $\pi_n^d$ and $\pi_n^{\mathcal{F}_n}$ in the last line. Altogether, we conclude that there exists a constant $C > 0$ such that $\Vert \underline{\mathbf{u}} - \underline{\tilde{\pi}}_n^d \mathbf{u} \Vert_{\mathbb{X}_n} \le C \Vert \mathbf{u} \Vert_{{\mathbf H}^{1+s}}$ which proves \eqref{eq:pinXd:boundedness}.

\begin{equation*}
      \Vert \underline{\mathbf{u}} - \underline{\tilde{\pi}}_n^d \mathbf{u} \Vert_{\mathbb{X}_n} \le \Vert \mathbf{u} - \PVol{\underline{\tilde{\pi}}_n^d \mathbf{u}} \Vert_{\mathbb{X}(\mathcal{T}_n)} + \Vert \rho^{1/2} \mathbf{R}^{\!l} (\underline{\mathbf{u}} -\underline{\tilde{\pi}}_n^d \mathbf{u}) \Vert_{\mathcal{T}_n}. 
   \end{equation*}

\begin{equation}\label{eq:pinXd:RBoundedness}
      \begin{aligned}
         \Vert \rho^{1/2} \mathbf{R}^{\!l} (\underline{\mathbf{u}} - \underline{\tilde{\pi}}_n^d \mathbf{u}) \Vert_{\mathcal{T}_n} &\lesssim \Vert \rho^{1/2} \mathfrak{h}^{-1/2} \hdgjump{\underline{\tilde{\pi}}_n^d \mathbf{u}}_{\mathbf{b}} \Vert_{\mathbf{L}^2(\partial \mathcal{T}_n)} \\
		   &\lesssim \Vert \rho^{1/2} \mathfrak{h}^{-1/2} (\mathbf{b} \cdot \boldsymbol{\nu}) P_{\boldsymbol{\nu}}^{\perp}(\pi_n^d \mathbf{u} - \pi_n^{\mathcal{F}_n}\mathbf{u}) \Vert_{\mathbf{L}^2(\partial \mathcal{T}_n)}\\
		   &\lesssim \Vert \rho^{1/2} \mathfrak{h}^{-1/2} (\mathbf{b} \cdot \boldsymbol{\nu})(\pi_n^d \mathbf{u} - \mathbf{u}) \Vert_{\mathbf{L}^2(\partial \mathcal{T}_n)} \\
         &\quad + \Vert \rho^{1/2} \mathfrak{h}^{-1/2} (\mathbf{b} \cdot \boldsymbol{\nu})(\pi_n^{\mathcal{F}_n} \mathbf{u} - \mathbf{u}) \Vert_{\mathbf{L}^2(\partial \mathcal{T}_n)}\\
         &\lesssim h^s_n \Vert \mathbf{u} \Vert_{{\mathbf H}^{1+s}},
      \end{aligned}
   \end{equation}

Due to the density of $\bm{C}^\infty_0$ in $\mathbb{X}$ \cite[Thm.~6]{HLS22H1}, we can choose $\tilde{\mathbf{u}} \in \bm{C}^\infty_0$ such that $\Vert \mathbf{u} - \tilde{\mathbf{u}} \Vert_{\mathbb{X}} < \epsilon$ for any $\epsilon > 0$. Then, we can estimate with \eqref{eq:dn:triangle} that 
\begin{equation*}
   d_n(\mathbf{u},p_n \mathbf{u}) \le d_n(\tilde{\mathbf{u}},p_n \tilde{\mathbf{u}}) + \Vert \tilde{\mathbf{u}} - \mathbf{u} \Vert_{\mathbb{X}}  + \Vert p_n (\tilde{\mathbf{u}} - \mathbf{u}) \Vert_{\mathbb{X}_n} \le d_n(\tilde{\mathbf{u}},p_n \tilde{\mathbf{u}}) + 2 \epsilon.
\end{equation*}
Thus, the claim follows from the previous \cref{lem:pnBoundedBypinX} and \cref{lem:pinXRates}.

\begin{equation*}
      d_n(\mathbf{u},p_n \mathbf{u}) \le d_n(\tilde{\mathbf{u}},p_n \tilde{\mathbf{u}}) + \Vert \tilde{\mathbf{u}} - \mathbf{u} \Vert_{\mathbb{X}}  + \Vert p_n (\tilde{\mathbf{u}} - \mathbf{u}) \Vert_{\mathbb{X}_n} \le d_n(\tilde{\mathbf{u}},p_n \tilde{\mathbf{u}}) + 2 \epsilon.
   \end{equation*}

\label{lem:dnupinXdtoZero}
   For all $\mathbf{u} \in {\mathbf H}^1_{\boldsymbol{\nu} 0}$, it holds that 
   \begin{equation}
      \lim_{n \to \infty} d_n(\mathbf{u},\underline{\pi}_n \mathbf{u}) = 0 \quad \text{and} \quad \lim_{n \to \infty} d_n(\mathbf{u},\underline{\tilde{\pi}}_n^d \mathbf{u}) = 0.
   \end{equation}

\begin{equation}
      \lim_{n \to \infty} d_n(\mathbf{u},\underline{\pi}_n \mathbf{u}) = 0 \quad \text{and} \quad \lim_{n \to \infty} d_n(\mathbf{u},\underline{\tilde{\pi}}_n^d \mathbf{u}) = 0.
   \end{equation}

   By construction of $\underline{\tilde{\pi}}_n^d$ and the approximation properties of $\pi_n^d$, we have for $\mathbf{u} \in {\mathbf H}^{1+s}$ that
   \begin{equation*}
	   d_n(\mathbf{u},\underline{\tilde{\pi}}_n^d \mathbf{u}) \lesssim \Vert \mathbf{u} - \pi_n^d \mathbf{u} \Vert_{\mathbb{X}(\mathcal{T}_n)} + \Vert \rho^{1/2} \mathbf{R}^{\!l} \underline{\tilde{\pi}}_n^d \mathbf{u} \Vert_{\mathcal{T}_n} \lesssim h^s \Vert \mathbf{u} \Vert_{{\mathbf H}^{1+s}}. 
   \end{equation*}
   \cref{lem:pinXRates} yields the same estimate for $\underline{\pi}_n$. 
   The proof of the claim then follows with similar density arguments as in the proof of \cref{lem:dnpnuToZero} with the additional technicality of constructing a smooth approximation that respects the boundary condition $\boldsymbol{\nu} \cdot \tilde{\mathbf{u}} = 0$ on $\partial \mathcal{O}$. For technical details, we refer to the proof of \cite[Lem.~6]{H23Hdiv}.

\begin{equation*}
	   d_n(\mathbf{u},\underline{\tilde{\pi}}_n^d \mathbf{u}) \lesssim \Vert \mathbf{u} - \pi_n^d \mathbf{u} \Vert_{\mathbb{X}(\mathcal{T}_n)} + \Vert \rho^{1/2} \mathbf{R}^{\!l} \underline{\tilde{\pi}}_n^d \mathbf{u} \Vert_{\mathcal{T}_n} \lesssim h^s \Vert \mathbf{u} \Vert_{{\mathbf H}^{1+s}}. 
   \end{equation*}

With \eqref{eq:def:pn}, we compute  
\begin{equation*}
   \begin{aligned}
      \Vert p_n \mathbf{u} \Vert_{\mathbb{X}_n}^2 &= \inner{p_n \mathbf{u}, p_n \mathbf{u}}_{\mathbb{X}_n} \\
      &= \innercsr{\operatorname{div} \mathbf{u}, \operatorname{div}_{\boldsymbol{\nu}}^n p_n \mathbf{u}}_{L^2} + \inner{\mathbf{u}, \PVol{p_n \mathbf{u}}}_{\mathbf{L}^2} + \innerr{\partial_{\mathbf{b}} \mathbf{u}, \mathbf{D}_{\mathbf{b}}^n p_n \mathbf{u}}_{\mathbf{L}^2} \\
      &= \Vert \mathbf{u} \Vert_{\mathbb{X}} + \innercsr{\operatorname{div} \mathbf{u}, \operatorname{div}_{\boldsymbol{\nu}}^n p_n \mathbf{u}  - \operatorname{div} \mathbf{u}}_{L^2} + \inner{\mathbf{u}, \PVol{p_n \mathbf{u}} - \mathbf{u}}_{\mathbf{L}^2} \\
      &\quad + \innerr{\partial_{\mathbf{b}} \mathbf{u}, \mathbf{D}_{\mathbf{b}}^n p_n \mathbf{u} - \partial_{\mathbf{b}} \mathbf{u}}_{\mathbf{L}^2}.
   \end{aligned} 
\end{equation*}
Since $\lim_{n \to \infty} d_n(\mathbf{u},p_n \mathbf{u}) = 0$ by \cref{lem:dnpnuToZero}, the claim follows from the estimate 
\begin{align*}
   \vert  &\innercsr{\operatorname{div} \mathbf{u}, \operatorname{div}_{\boldsymbol{\nu}}^n p_n \mathbf{u}  - \operatorname{div} \mathbf{u}}_{L^2} + \inner{\mathbf{u}, \PVol{p_n \mathbf{u}}  - \mathbf{u}}_{\mathbf{L}^2} + \innerr{\partial_{\mathbf{b}} \mathbf{u}, \mathbf{D}_{\mathbf{b}}^n p_n \mathbf{u} - \partial_{\mathbf{b}} \mathbf{u}}_{\mathbf{L}^2} \vert \\
   \le &\Vert \mathbf{u} \Vert_{\mathbb{X}} d_n(\mathbf{u},p_n \mathbf{u}). 
\end{align*}

\begin{equation*}
      \begin{aligned}
         \Vert p_n \mathbf{u} \Vert_{\mathbb{X}_n}^2 &= \inner{p_n \mathbf{u}, p_n \mathbf{u}}_{\mathbb{X}_n} \\
         &= \innercsr{\operatorname{div} \mathbf{u}, \operatorname{div}_{\boldsymbol{\nu}}^n p_n \mathbf{u}}_{L^2} + \inner{\mathbf{u}, \PVol{p_n \mathbf{u}}}_{\mathbf{L}^2} + \innerr{\partial_{\mathbf{b}} \mathbf{u}, \mathbf{D}_{\mathbf{b}}^n p_n \mathbf{u}}_{\mathbf{L}^2} \\
         &= \Vert \mathbf{u} \Vert_{\mathbb{X}} + \innercsr{\operatorname{div} \mathbf{u}, \operatorname{div}_{\boldsymbol{\nu}}^n p_n \mathbf{u}  - \operatorname{div} \mathbf{u}}_{L^2} + \inner{\mathbf{u}, \PVol{p_n \mathbf{u}} - \mathbf{u}}_{\mathbf{L}^2} \\
         &\quad + \innerr{\partial_{\mathbf{b}} \mathbf{u}, \mathbf{D}_{\mathbf{b}}^n p_n \mathbf{u} - \partial_{\mathbf{b}} \mathbf{u}}_{\mathbf{L}^2}.
      \end{aligned} 
   \end{equation*}

\begin{align*}
      \vert  &\innercsr{\operatorname{div} \mathbf{u}, \operatorname{div}_{\boldsymbol{\nu}}^n p_n \mathbf{u}  - \operatorname{div} \mathbf{u}}_{L^2} + \inner{\mathbf{u}, \PVol{p_n \mathbf{u}}  - \mathbf{u}}_{\mathbf{L}^2} + \innerr{\partial_{\mathbf{b}} \mathbf{u}, \mathbf{D}_{\mathbf{b}}^n p_n \mathbf{u} - \partial_{\mathbf{b}} \mathbf{u}}_{\mathbf{L}^2} \vert \\
      \le &\Vert \mathbf{u} \Vert_{\mathbb{X}} d_n(\mathbf{u},p_n \mathbf{u}). 
   \end{align*}

We modify standard arguments from the DG-case, see e.g.~\cite{BO09} and \cite{H23Hdiv}, to the HDG setting, see also \cite{KCR23}. \\ 
By assumption, the sequences $\PVol{\mathbf{u}_n}$, $\rho \mathbf{D}_{\mathbf{b}}^n \mathbf{u}_n$ and $c_s^2 \rho \operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{u}_n$ are bounded in $\mathbf{L}^2$ and $L^2$, respectively. Thus, there exist a subsequence $\mathbb{N}' \subset \mathbb{N}$ and elements $\mathbf{u}, \bm{g} \in \mathbf{L}^2$, $q \in L^2$ such that $\PVol{\mathbf{u}_n} \overset{\mathbf{L}^2}{\rightharpoonup} \mathbf{u}$, $c_s^2 \rho \operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{u}_n \overset{L^2}{\rightharpoonup} q$ and $\rho \mathbf{D}_{\mathbf{b}}^n \mathbf{u}_n \overset{\mathbf{L}^2}{\rightharpoonup} \bm{g}$. It remains to show that $\bm{g} = \rho \partial_{\mathbf{b}} \mathbf{u}$ and $q = c_s^2 \rho \operatorname{div} \mathbf{u}$. We only show the former, as the latter follows with a similar argumentation for the scalar lifting operator $R^l$, see also \cite[Lem.~6.7]{Thesis_vB23}. Let $\bm{\psi} \in \bm{C}^\infty_0$ and $\bm{\psi}_n$ be the lowest order standard ${\mathbf H}^1$-interpolant of $\bm{\psi}$ on $\mathcal{T}_n$. Then, we compute with element-wise partial integration
\begin{equation}\label{eq:weakConvergence:partialInt}
   \begin{aligned}
      - \inner{&\PVol{\mathbf{u}_n}, \rho \partial_{\mathbf{b}} \bm{\psi}}_{\mathcal{T}_n}  \\
      &= \innerr{\partial_{\mathbf{b}} \PVol{\mathbf{u}_n}, \bm{\psi}}_{\mathcal{T}_n} - \innerr{(\mathbf{b} \cdot \boldsymbol{\nu}) \PVol{\mathbf{u}_n}, \bm{\psi}}_{\partial \mathcal{T}_n} + \underbrace{\innerr{(\mathbf{b} \cdot \boldsymbol{\nu}) \PFac{\mathbf{u}_n}, \bm{\psi}}_{\partial \mathcal{T}_n}}_{=0} \\[-0.25cm]
      &= \innerr{\partial_{\mathbf{b}} \PVol{\mathbf{u}_n}, \bm{\psi}}_{\mathcal{T}_n} - \innerr{\hdgjump{\mathbf{u}_n}_{\mathbf{b}}, \bm{\psi}}_{\partial \mathcal{T}_n} \\
      \overset{\eqref{eq:VecLift}}&{=} \innerr{\partial_{\mathbf{b}} \PVol{\mathbf{u}_n}, \bm{\psi}}_{\mathcal{T}_n} - \innerr{\hdgjump{\mathbf{u}_n}_{\mathbf{b}}, \bm{\psi} - \bm{\psi}_n}_{\partial \mathcal{T}_n} + \innerr{\mathbf{R}^{\!l} \mathbf{u}_n, \bm{\psi}_n}_{\mathcal{T}_n} \\
      \overset{\eqref{eq:discreteDiffs}}&{=} \innerr{\partial_{\mathbf{b}} \PVol{\mathbf{u}_n}, \bm{\psi} - \bm{\psi}_n}_{\mathcal{T}_n} - \innerr{\hdgjump{\mathbf{u}_n}_{\mathbf{b}}, \bm{\psi} - \bm{\psi}_n}_{\partial \mathcal{T}_n} + \innerr{\mathbf{D}_{\mathbf{b}}^n \mathbf{u}_n, \bm{\psi}_n}_{\mathcal{T}_n} \\
      &= -\inner{\PVol{\mathbf{u}_n}, \rho \partial_{\mathbf{b}}  \left( \bm{\psi}-\bm{\psi}_n  \right)}_{\mathcal{T}_n} + \innerr{\mathbf{D}_{\mathbf{b}}^n \mathbf{u}_n, \bm{\psi}_n}_{\mathcal{T}_n},
   \end{aligned}
\end{equation}
where we recall that $\operatorname{div}(\rho \mathbf{b}) = 0$ by assumption. Since $\Vert \bm{\psi} - \bm{\psi}_n \Vert_{{\mathbf H}^1} \lesssim h_n \Vert \bm{\psi} \Vert_{{\mathbf H}^2}$ and $\Vert \mathbf{u}_n \Vert_{\mathbb{X}_n} \lesssim 1$, it follows that $ \lim_{n \to \infty} \innerr{\mathbf{D}_{\mathbf{b}}^n \mathbf{u}_n, \bm{\psi}_n}_{\mathcal{T}_n} = \lim_{n \to \infty} - \inner{\PVol{\mathbf{u}_n}, \rho \partial_{\mathbf{b}} \bm{\psi}_n}_{\mathcal{T}_n}$. Thus, we obtain
\begin{align*}
   \inner{\bm{g}, \bm{\psi}} &= \lim_{n \rightarrow \infty} \innerr{\mathbf{D}_{\mathbf{b}}^n \mathbf{u}_n, \bm{\psi}} = \lim_{n \to \infty} \left( \innerr{\mathbf{D}_{\mathbf{b}}^n \mathbf{u}_n, \bm{\psi} - \bm{\psi_n}}_{\mathcal{T}_n} + \innerr{\mathbf{D}_{\mathbf{b}}^n \mathbf{u}_n, \bm{\psi}_n}_{\mathcal{T}_n} \right) \\
   \overset{\eqref{eq:weakConvergence:partialInt}}&{=} \lim_{n \rightarrow \infty} - \inner{\PVol{\mathbf{u}_n}, \rho \partial_{\mathbf{b}} \bm{\psi}}_{\mathcal{T}_n} = - \inner{\mathbf{u}, \rho \partial_{\mathbf{b}} \bm{\psi}}_{\mathcal{T}_n}.
\end{align*}
Consequently, it holds that $\bm{g} = \rho \partial_{\mathbf{b}} \mathbf{u}$ and with similar arguments $q = c_s^2 \rho \operatorname{div} \mathbf{u}$.

\begin{equation}\label{eq:weakConvergence:partialInt}
      \begin{aligned}
