\begin{align*}
   \operatorname{div} \pi_n^d \nabla \tilde{v} &= \pi_n^l \operatorname{div} \nabla \tilde{v} \\
   \overset{\eqref{eq:Xdecomp:discr}}&{=} \pi_n^l \left( - (P_{L^2_0} \mathbf{q} \cdot + M) \nabla \tilde{v} + (\operatorname{div}_{\boldsymbol{\nu}}^n + \pi_n^l P_{L^2_0} \mathbf{q} \cdot \! + M_n) \mathbf{u}_n \right) \\
   &= - (P_{L^2_0} \mathbf{q} \cdot + M) \nabla \tilde{v} + (\operatorname{div}_{\boldsymbol{\nu}}^n + \pi_n^l P_{L^2_0} \mathbf{q} \cdot \! + M_n) \mathbf{u}_n \\
   &\qquad + (\mathrm{id} - \pi_n^l)(P_{L^2_0} \mathbf{q} \cdot + M) \nabla \tilde{v} + (\pi_n^l - \mathrm{id})M_n \mathbf{u}_n \\
   \overset{\eqref{eq:Xdecomp:discr}}&{=} \operatorname{div} \nabla \tilde{v} + (\mathrm{id} - \pi_n^l)(P_{L^2_0} \mathbf{q} \cdot + M) S_n \mathbf{u}_n + (\pi_n^l - \mathrm{id}) M_n \mathbf{u}_n \\
   &=: \operatorname{div} \nabla \tilde{v} + \hat{O}_n \mathbf{u}_n.
\end{align*}
Thus, we have that 
\begin{equation}\label{eq:divPvnEquals}
   \begin{aligned}
      \Vert c_s \rho^{1/2} \operatorname{div}_{\boldsymbol{\nu}}^n P_{V_n} \mathbf{u}_n \Vert^2_{\mathcal{T}_n} &= \langle c_s^2 \rho \operatorname{div} \pi_n^d \nabla \tilde{v}, \operatorname{div} \pi_n^d \nabla \tilde{v} \rangle \\
      &= \langle c_s^2 \rho \operatorname{div} \nabla \tilde{v}, \operatorname{div} \nabla \tilde{v} \rangle + \langle \check{O}_n \mathbf{u}_n, \mathbf{u}_n \rangle_{\mathbb{X}_n}, 
   \end{aligned}
\end{equation} 
where we define the operator $\check{O}_n$ through 
\begin{equation*}
   \begin{aligned}
      \langle \check{O}_n \mathbf{u}_n, \mathbf{u}_n' \rangle_{\mathbb{X}_n} \coloneqq &\langle c_s^2 \rho \operatorname{div} \pi_n^d \nabla \tilde{v}, \hat{O}_n \mathbf{u}_n' \rangle + \langle c_s^2 \rho \hat{O}_n \mathbf{u}_n, \operatorname{div} (\pi_n^d \nabla \tilde{v})' \rangle \\
      &+ \langle c_s^2 \rho \hat{O}_n \mathbf{u}_n, \hat{O}_n \mathbf{u}_n' \rangle.
   \end{aligned}
\end{equation*}
With similar arguments as in \cref{lem:PvIdempotent}, we can show $\lim_{n \to \infty} \Vert \hat{O}_n \Vert_{L(\mathbb{X}_n,L^2_0)} = 0$ and thus $\lim_{n \to \infty} \Vert \check{O}_n \Vert_{L(\mathbb{X}_n)} = 0$.

In the following, we use similar techniques as in the proof of \cite[Thm.~3.5]{HH21} to show that the first term can be estimated suitably by a weighted ${\mathbf H}^1$-seminorm. By assumption, $\mathcal{O}$ is a convex Lipschitz polyhedron and thus, we can apply \cite[Thm.~3.1.1.2]{G11} to estimate for any $\mathbf{v} \in {\mathbf H}^1_{\boldsymbol{\nu} 0}$
\begin{equation}\label{eq:GrisvardEstimate}
   \Vert \operatorname{div} (\mathbf{v}) \Vert^2_{L^2} \! = \! \! \! \sum_{i,j = 1}^d \langle \partial_{x_j} \mathbf{v}_i, \partial_{x_i} \mathbf{v}_j \rangle_{\mathbf{L}^2} \! - \! \! \int_{\partial \mathcal{O}} \! \! \! \! \mathcal{B}(P_{\boldsymbol{\nu}}^\perp \mathbf{v}, P_{\boldsymbol{\nu}}^\perp \mathbf{v}) \mathrm{d}s \ge \! \! \! \sum_{i,j = 1}^d \langle \partial_{x_j} \mathbf{v}_i, \partial_{x_i} \mathbf{v}_j \rangle_{\mathbf{L}^2}.
\end{equation}
where $\mathcal{B}(\bm{\tau},\bm{\tau}') := -\partial_{\bm{\tau}} \boldsymbol{\nu} \cdot \overline{\bm{\tau}'}$ is the second fundamental quadratic form of $\partial \mathcal{O}$ applied to tangential vector fields $\bm{\tau},\bm{\tau}'$ and $\partial_{\bm{\tau}}$ is the tangential derivative. The last estimate follows since the form $\mathcal{B}$ is non-positive for convex domains \cite[Sec.~3.1.1]{G11}.

For any $\eta \in W^{1,\infty}(\mathcal{O})$, the product rule gives that $\eta \operatorname{div} \mathbf{v} = \operatorname{div}(\eta \mathbf{v}) - \mathbf{v} \cdot \nabla \eta$ and thus we estimate with the weighted Young's inequality for any $\delta \in (0,1)$ that 
\begin{equation}\label{eq:etaDivVFirstEst}
   \Vert \eta \operatorname{div} \mathbf{v} \Vert^2_{L^2} \ge (1-\delta) \Vert \operatorname{div} (\eta \mathbf{v}) \Vert^2_{\mathbf{L}^2} + (1-\frac{1}{\delta}) \Vert \mathbf{v} \cdot \nabla \eta \Vert_{\mathbf{L}^2}^2. 
\end{equation}
Since $\eta \mathbf{v} \in {\mathbf H}^1_{\boldsymbol{\nu} 0}$, we can apply \eqref{eq:GrisvardEstimate} to the first term to obtain 
\begin{equation*}
   \begin{aligned}
      \Vert \operatorname{div} (\eta \mathbf{v}) \Vert^2_{L^2} &\ge \sum_{i,j=1}^d \langle \partial_{x_j} (\eta \mathbf{v}_i), \partial_{x_i} (\eta \mathbf{v}_j) \rangle_{\mathbf{L}^2} \\
      &\ge \sum_{i,j=1}^d \big( \langle \eta \partial_{x_j} \mathbf{v}_{i}, \eta \partial_{x_i} \mathbf{v}_{j} \rangle_{\mathbf{L}^2} + \langle \mathbf{v}_i \partial_{x_j} \eta, \mathbf{v}_j \partial_{x_i} \eta \rangle_{\mathbf{L}^2} + \langle \mathbf{v}_i \partial_{x_j} \eta, \eta \partial_{x_i} \mathbf{v}_j \rangle_{\mathbf{L}^2} \\
      &\qquad+ \langle \eta \partial_{x_j} \mathbf{v}_i, \mathbf{v}_j \partial_{x_i} \eta \rangle_{\mathbf{L}^2} \big). 
   \end{aligned} 
\end{equation*} 
Applying this estimate to $\mathbf{v} = \nabla \tilde{v}$, we notice that $\partial_{x_j} \mathbf{v}_i = \partial_{x_i} \mathbf{v}_j$ and consequently
\begin{equation*}
   \begin{aligned}
      \Vert \operatorname{div} (\eta \mathbf{v}) \Vert^2_{L^2} &\ge \Vert \eta \nabla \mathbf{v} \Vert^2_{\mathbf{L}^2} + \sum_{i,j=1}^d \big( \langle \mathbf{v}_i \partial_{x_j} \eta, \mathbf{v}_j \partial_{x_i} \eta \rangle_{\mathbf{L}^2} + \langle \mathbf{v}_i \partial_{x_j} \eta, \eta \partial_{x_i} \mathbf{v}_j \rangle_{\mathbf{L}^2} \\
      &\qquad+ \langle \eta \partial_{x_j} \mathbf{v}_i, \mathbf{v}_j \partial_{x_i} \eta \rangle_{\mathbf{L}^2} \big) \\
      &\ge \Vert \eta \nabla \mathbf{v} \Vert^2_{\mathbf{L}^2} - C \left( \Vert \mathbf{v} \cdot \nabla \eta \Vert^2_{\mathbf{L}^2} + \Vert \eta \nabla \mathbf{v} \Vert_{\mathbf{L}^2} \Vert \mathbf{v} \cdot \nabla \eta \Vert_{\mathbf{L}^2} \right) \\
      &\ge  (1-\delta) \Vert \eta \nabla \mathbf{v} \Vert^2_{\mathbf{L}^2} - (C+\frac{1}{4\delta}) \Vert \mathbf{v} \cdot \nabla \eta \Vert^2_{\mathbf{L}^2},
   \end{aligned} 
\end{equation*}
where we use the Cauchy-Schwarz and the weighted Young's inequality in the last two lines. Inserting this into the estimate \eqref{eq:etaDivVFirstEst} yields 
\begin{equation*}
   \Vert \eta \operatorname{div} \mathbf{v} \Vert^2_{L^2} \ge  (1-\delta)^2 \Vert \eta \nabla \mathbf{v} \Vert^2_{\mathbf{L}^2} + \underbrace{\left( C(\delta-1) - \frac{5}{4\delta} + \frac{5}{4} \right)}_{=: - \tilde{C}_{\delta}} \Vert \mathbf{v} \cdot \nabla \eta \Vert^2_{\mathbf{L}^2},
\end{equation*}
where we note that $\tilde{C}_{\delta} \ge 0$ for all $\delta \in (0,1)$. Since $\eta \in W^{1,\infty}$ is Lipschitz continuous, $\nabla \eta$ is bounded such that 
$\Vert \mathbf{v} \cdot \nabla \eta \Vert^2_{\mathbf{L}^2} \le C_{\nabla \eta} \Vert \mathbf{v} \Vert_{\mathbf{L}^2}$. Inserting $\mathbf{v} = \nabla \tilde{v} = S_n \mathbf{u}_n$ and $\eta = c_s \rho^{1/2}$ we obtain together with \eqref{eq:divPvnEquals} that 
\begin{equation}
   \! \! \Vert c_s \rho^{1/2} \! \operatorname{div}_{\boldsymbol{\nu}}^n P_{V_n} \! \mathbf{u}_n \Vert^2_{\mathcal{T}_n} \ge (1\!-\!\delta)^2 \vert S_n \mathbf{u}_n \vert^2_{{\mathbf H}^1_{c_s^2 \rho}} \!  \! \! \! \!-\! C_{\delta} \Vert S_n \mathbf{u}_n \Vert^2_{\mathbf{L}^2} + \langle \check{O}_n \mathbf{u}_n, \!\mathbf{u}_n \rangle_{\mathbb{X}_n}\!,
\end{equation}
where $C_{\delta} \coloneqq \tilde{C}_{\delta} C_{\nabla \eta}$. Thus, the claim is proven.

