   We split the proof of the statement into four steps. In the first step, we define the sequences $\seq{B}$ and $\seq{K}$ and argue that indeed $A_n T_n = B_n + K_n$. Afterwards, we show in the second and third step that the sequence $\seq{B}$ is \hyperlink{stable}{stable}. In the last step, we show that there exists a bijective operator $B \in L(\mathbb{X})$ and a compact operator $K \in L(\mathbb{X})$ such that $AT = B + K$ and $B_n$ \hyperlink{approximate}{approximates}~$B$. In the following, we denote $\colorv{\mathbf{v}_n} \coloneqq P_{V_n} \mathbf{u}_n$, $\colorw{\mathbf{w}_n} \coloneqq \mathbf{u}_n - \colorv{\mathbf{v}_n}$ for an element $\mathbf{u}_n \in \mathbb{X}_n$ and $\colorv{\mathbf{v}_n'}, \colorw{\mathbf{w}_n'}$ defined analogously for an element $\mathbf{u}_n' \in \mathbb{X}_n$. \\[0.8ex]
   \emph{\underline{Step 1:} Definition of $B_n$ and $K_n$.} We want to define $B_n, K_n \in L(\mathbb{X}_n)$ such that $A_n T_n = B_n + K_n$, where $\seq{B}$ is uniformly coercive and $\seq{K}$ is \hyperlink{compactseq}{compact}. In particular, we define $B_n = B_n^{(1)} + B_n^{(2)}$, where $B_n^{(1)}$ is constructed to yield the essential control of the $\Vert \cdot \Vert_{\mathbb{X}_n}$-norm and $B_n^{(2)}$ contains the remaining terms, which we will estimate in \emph{Step 3}. We add compact terms $K_n^{(1)}$ and $K_n^{(2)}$ to both operators which are subtracted again through $K_n = -K_n^{(1)} - K_n^{(2)}$.   

   We will consider a splitting $a_n(\cdot,\cdot) = a_n^{(1)}(\cdot,\cdot) + a_n^{(2)}(\cdot,\cdot)$ so that terms that directly help for ($T_n$-)coercivity will be collected in $a_n^{(1)}(\cdot,\cdot)$ and the remainder will be collected in $a_n^{(2)}(\cdot,\cdot)$.
   By construction, $T_n$ swaps the sign in front of \colorw{$\mathbf{w}_n$} such that $\langle A_n T_n \mathbf{u}_n, \mathbf{u}_n' \rangle = a_n(\colorv{\mathbf{v}_n} - \colorw{\mathbf{w}_n}, \colorv{\mathbf{v}_n'} + \colorw{\mathbf{w}_n'})$. 

   We recall $\mathbf{q} \coloneqq c_s^{-2} \rho^{-1} \nabla p$, the associated rewriting of the sesquilinear form \eqref{eq:aCont:q}, and note that we can use a corresponding split on the discrete level: $a_n(\cdot,\cdot) = a_n^{(\operatorname{div} + \mathbf{q} \cdot)}(\cdot,\cdot) +s_n(\cdot,\cdot) - a_n^{\partial_{\mathbf{b}}}(\cdot,\cdot) + a_n^{(r - \mathbf{q} \cdot)}(\cdot,\cdot)$. 

   We have that \colorv{$\operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{v}_n = \operatorname{div} \mathbf{v}_{\tau}$} and thus 
   \begin{equation}\label{eq:adiv:1}
      \begin{aligned}
         \hspace*{-2cm}a_n^{(\operatorname{div} + \mathbf{q} \cdot)}&(T_n \mathbf{u}_n,\mathbf{u}_n') =  
         \inner{c_s^2 \rho (\operatorname{div}_{\boldsymbol{\nu}}^n + \mathbf{q} \cdot) 
         \mathbf{u}_n,

         (\operatorname{div}_{\boldsymbol{\nu}}^n + \mathbf{q} \cdot) 

         \mathbf{u}_n'
         } 
         = 
         \textstyle{\sum_{J=\colorvv{I},\colorvw{II},\colorwv{III},\colorww{IV}}} (\ref{eq:adiv:1}_{\text{\tiny J\!}})
         \\
         = & \color{vv} \inner{c_s^2 \rho (\operatorname{div} + \mathbf{q} \cdot) \mathbf{v}_{\tau}, (\operatorname{div} + \mathbf{q} \cdot) \mathbf{v}_{\tau}'} \color{vw} + \inner{c_s^2 \rho (\operatorname{div} + \mathbf{q} \cdot) \mathbf{v}_{\tau}, (\operatorname{div}_{\boldsymbol{\nu}}^n + \mathbf{q} \cdot) \mathbf{w}_n'} \\
         & \color{wv} -\inner{c_s^2 \rho (\operatorname{div}_{\boldsymbol{\nu}}^n + \mathbf{q} \cdot) \mathbf{w}_n, (\operatorname{div} + \mathbf{q} \cdot) \mathbf{v}_{\tau}'} \color{ww}- \inner{c_s^2 \rho (\operatorname{div}_{\boldsymbol{\nu}}^n + \mathbf{q} \cdot) \mathbf{w}_n, (\operatorname{div}_{\boldsymbol{\nu}}^n + \mathbf{q} \cdot) \mathbf{w}_n'} 
      \end{aligned}
   \end{equation}
   The $\operatorname{div}$-parts of the first term in \colorvv{$(\ref{eq:adiv:1}_{\text{\tiny I\!}})$} will directly be used in $a_n^{(1)}(\cdot,\cdot)$ to control the divergence, below. 
   To rewrite \colorww{$(\ref{eq:adiv:1}_{\text{\tiny IV\!}})$}, we want to use that $(\operatorname{div}_{\boldsymbol{\nu}}^n + \pi_n^l P_{L^2_0} \mathbf{q} \cdot ) \mathbf{w}_n \stackrel{\eqref{eq:divwnEquals}}{=} -M_n \mathbf{w}_n - \tilde{O}_n \mathbf{u}_n$ for both arguments, so we shift in the terms involving the projection $\pi_n^l P_{L^2_0}$.   
   Then, we obtain\footnotemark \ that
   \begin{align}

      \colorww{(\ref{eq:adiv:1}_{\text{\tiny IV\!}})} =  &- \!\inner{c_s^2 \rho (M_n \mathbf{w}_{n} \!+\! \tilde{O}_n \mathbf{u}_n), M_n \mathbf{w}_n' \!+\! \tilde{O}_n \mathbf{u}_n'} \! \color{ww} - \! \inner{c_s^2 \rho \operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{w}_n, (\mathrm{id} \!- \pi_n^l P_{L^2_0}) \mathbf{q} \!\cdot\! \mathbf{w}_n'} \!\!\!\!\!\!\!\!\! \nonumber\\
      & \color{ww}- \inner{c_s^2 \rho (\mathrm{id}-\pi_n^l P_{L^2_0} )\mathbf{q} \cdot \mathbf{w}_n, \operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{w}_n'} \! + \! \inner{c_s^2 \rho \pi_n^l P_{L^2_0} \mathbf{q} \cdot \mathbf{w}_n,  \pi_n^l P_{L^2_0} \mathbf{q} \cdot \mathbf{w}_n'}  \!\!\!\!\!\!\!\!\! \label{eq:adiv:2} \\
	  & \color{ww} - \! \inner{c_s^2 \rho \mathbf{q} \otimes \mathbf{q} \cdot \mathbf{w}_{\tau},  \mathbf{w}_{\tau}'}  \!\!\!\!\!\!\!\!\! \nonumber.
   \end{align}

   \footnotetext{We use that $\langle a+b,a'+b' \rangle = \langle a +c,a'+c' \rangle + \langle a,b'-c' \rangle + \langle b-c,a' \rangle + \langle b,b' \rangle - \langle c,c' \rangle$ with $a = \operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{w}_n$, $b = \mathbf{q} \cdot \mathbf{w}_n$, and $c = \pi_n^l P_{L^2_0} \mathbf{q} \cdot \mathbf{w}_n$; $a',b',c'$ analogously with $\mathbf{w}_n'$.}

   We apply the same argumentation to the mixed terms \colorvw{$(\ref{eq:adiv:1}_{\text{\tiny II\!}})$} and \colorwv{$(\ref{eq:adiv:1}_{\text{\tiny III\!}})$}, and note that the terms $\inner{c_s^2 \rho \mathbf{q} \otimes \mathbf{q} \cdot \mathbf{z}_{\tau},  \mathbf{z}_{\tau}'}$, $\mathbf{z}_{\tau} \in \{\mathbf{v}_{\tau}, \mathbf{w}_{\tau} \}$, $\mathbf{z}_{\tau}' \in \{\mathbf{v}_{\tau}',\mathbf{w}_{\tau}'\}$, cancel out with the $\mathbf{q}$-terms in $a_n^{(r - \mathbf{q} \cdot)}(T_n \mathbf{u}_n,\mathbf{u}_n')$. Thus, these terms do not appear in the following, and we are left with $\hyperref[eq:an:components:aremn]{a^{r}_n}(\cdot,\cdot)$ instead of $a_n^{(r - \mathbf{q} \cdot)}(\cdot,\cdot)$.

   For $a_n^{(1)}(\cdot,\cdot)$, we will only use the fourth term of \eqref{eq:adiv:2} and shift the remaining terms into $a_n^{(2)}(\cdot,\cdot)$. Hence, we define
   \begin{subequations}
      \begin{align}
         \tag{$\theequation{}|a_n^{(1)}$}\label{eq:anI}
         a_n^{(1)}(&\mathbf{u}_n,\mathbf{u}_n') \coloneqq  \\ 
         \tag{$\theequation{}a|a_n^{(1)}$}
            &\color{vv}\langle c_s^2 \rho \operatorname{div} \mathbf{v}_{\tau}, \operatorname{div} \mathbf{v}_{\tau}' \rangle \color{ww}+ \langle c^2_s \rho \pi_n^l P_{L^2_0} \mathbf{q} \cdot \mathbf{w}_{\tau}, \pi_n^l P_{L^2_0} \mathbf{q} \cdot \mathbf{w}_{\tau}' \rangle - s_n(\mathbf{w}_n,\mathbf{w}_n') \label{eq:anI:1} \\
            \tag{$\theequation{}b|a_n^{(1)}$}
            &\color{vv}- \langle \rho i \mathbf{D}_{\mathbf{b}}^n \mathbf{v}_n, i \mathbf{D}_{\mathbf{b}}^n \mathbf{v}_n' \rangle \color{ww}+ \langle \rho (\omega\!+\!i\mathbf{D}_{\mathbf{b}}^n\!\!+\!i\Omega\times) \mathbf{w}_n, (\omega\!+\!i\mathbf{D}_{\mathbf{b}}^n\!\!+\!i\Omega\times) \mathbf{w}_n' \rangle \label{eq:anI:2}\\
            \tag{$\theequation{}c|a_n^{(1)}$}
            &\color{wv}+ \langle \rho (\omega\!+\!i\mathbf{D}_{\mathbf{b}}^n\!\!+\!i\Omega\times) \mathbf{w}_n, i \mathbf{D}_{\mathbf{b}}^n \mathbf{v}_n' \rangle 
            \color{vw}- \langle \rho i \mathbf{D}_{\mathbf{b}}^n \mathbf{v}_n, (\omega+i\mathbf{D}_{\mathbf{b}}^n+i\Omega\times) \mathbf{w}_n' \rangle \label{eq:anI:3}\\
            \tag{$\theequation{}d|a_n^{(1)}$}
            &\color{ww}+ \langle \rho (\underline{\underline{m}} + i \omega \gamma) \mathbf{w}_{\tau}, \mathbf{w}_{\tau}' \rangle. \label{eq:anI:4}
      \end{align}
   \end{subequations}
   The $\operatorname{div}$-terms of \colorvv{$(\ref{eq:adiv:1}_{\text{\tiny I\!}})$} and the fourth term in \eqref{eq:adiv:2} from $a_n^{(\operatorname{div} + \mathbf{q} \cdot)}(T_n \mathbf{u}_n, \mathbf{u}_n')$ together with 
   $s_n(T_n \mathbf{u}_n, \mathbf{u}_n')$ form line \eqref{eq:anI:1}, where we note that $s_n(T_n \mathbf{u}_n, \mathbf{u}_n') = \colorww{ - s_n(\mathbf{w}_n,\mathbf{w}_n')}$ since $\hdgjump{P_{V_n} \mathbf{u}_n}_{\boldsymbol{\nu}} = 0$ for all $\mathbf{u}_n \in \mathbb{X}_n$ by construction of $P_{V_n}$. 
   The terms in the lines \eqref{eq:anI:2} and \eqref{eq:anI:3} arise naturally from a selection of terms from $\hyperref[eq:an:components:aconvn]{a^{\partial_{\mathbf{b}}}_n}(T_n \mathbf{u}_n, \mathbf{u}_n')$. By definition of $\underline{\underline{m}} = - \rho^{-1} \mathrm{Hess}(p) + \mathrm{Hess}(\phi)$, we can write $\hyperref[eq:an:components:aremn]{a^{r}_n}(\mathbf{u}_n,\mathbf{u}_n') = - \langle \rho(\underline{\underline{m}} + i \omega \gamma) \mathbf{u}_n, \mathbf{u}_n' \rangle$, which is where the line \eqref{eq:anI:4} originates from. 

   Below, in \emph{Step 2}, we want to estimate these terms from below by applying \cref{lem:ddiffbEstimate,lem:ddivEstimate}. To this end, we add suitable compact terms to $B_n^{(1)}$ which we simultaneously subtract from $K_n$. For $C_1 > 0$ to be specified later on, we set
   \begin{align}
      \tag{$\theequation{}|K_n^{(1)}$}
	  \!\!\!\!\!\!\langle K_n^{(1)} \mathbf{u}_n,\mathbf{u}_n' \rangle_{\mathbb{X}_n} \!\!\coloneqq\! \colorvv{\langle \mathbf{v}_{\tau},\! \mathbf{v}_{\tau}' \rangle} \! + \! C_1 \langle S_n \mathbf{u}_n, \!S_n \mathbf{u}_n' \rangle \! + \! \colorww{\langle c_s^2 \rho M_n \mathbf{w}_{n},\! M_n \mathbf{w}_{n}' \rangle}\!  + \! \langle c_s^2 \rho \tilde{O}_n \mathbf{u}_n,\! \tilde{O}_n \mathbf{u}_n' \rangle.\!\!\!\!\!\!\!\!\! \label{eq:KnI}
   \end{align}
   Then, we define $\inner{B_n^{(1)} \mathbf{u}_n, \mathbf{u}_n'}_{\mathbb{X}_n} \coloneqq a_n^{(1)}(\mathbf{u}_n,\mathbf{u}_n') + \langle K_n^{(1)} \mathbf{u}_n,\mathbf{u}_n' \rangle_{\mathbb{X}_n}$.
   To account for the remaining terms in $a_n(T_n \mathbf{u}_n, \mathbf{u}_n')$, 



   we define 
   \begin{equation}
      \tag{$\theequation{}|a_n^{(2)}$}
      a_n^{(2)} (\mathbf{u}_n, \mathbf{u}_n') \coloneqq a_n(T_n \mathbf{u}_n, \mathbf{u}_n') - a_n^{(1)}(\mathbf{u}_n,\mathbf{u}_n').
   \end{equation}
   To treat the terms in $a_n^{(2)} (\mathbf{u}_n, \mathbf{u}_n')$ we add suitable compact terms which together with $a_n^{(2)} (\mathbf{u}_n, \mathbf{u}_n')$ can be bounded from below. To this end, we  define, for $C_2 > 0$ to be specified later on,
   \begin{subequations}\label{eq:KnII}
      \begin{align}
         \tag{$\theequation{}a|K_n^{(2)}$}
         \langle K_n^{(2)} &\mathbf{u}_n,\mathbf{u}_n'\rangle_{\mathbb{X}_n} \coloneqq C_2 \big(\colorvv{\langle \mathbf{v}_{\tau}, \mathbf{v}_{\tau}'\rangle} + \langle S_n \mathbf{u}_n, S_n \mathbf{u}_n' \rangle + \langle c_s^2 \rho \tilde{O}_n \mathbf{u}_n, \tilde{O}_n \mathbf{u}_n' \rangle \\
         \tag{$\theequation{}b|K_n^{(2)}$}
         & + \colorww{\langle c_s^2 \rho M_n \mathbf{w}_{n}, M_n \mathbf{w}_{n}' \rangle} + \colorww{\langle \text{mean}(\mathbf{q} \cdot \mathbf{w}_{\tau}), \text{mean}(\mathbf{q} \cdot \mathbf{w}_{\tau}') \rangle} \big)
      \end{align}
   \end{subequations}
   where $\text{mean}$ denotes the mean value operator $\frac{1}{\mathcal{O}}\int_{\mathcal{O}} \cdot d \mathbf{x}$,
   and set $\inner{B_n^{(2)} \mathbf{u}_n, \mathbf{u}_n'}_{\mathbb{X}_n} \coloneqq a_n^{(2)}(\mathbf{u}_n, \mathbf{u}_n') + \langle K_n^{(2)} \mathbf{u}_n, \mathbf{u}_n' \rangle_{\mathbb{X}_n}$,  
   which we analyze in \emph{Step 3}. 

   With $K_n \coloneqq - K_n^{(1)} - K_n^{(2)}$ and $B_n \coloneqq B_n^{(1)} + B_n^{(2)}$, we then obtain that $A_n T_n = B_n + K_n$. The explicit expressions for the operators $B_n^{(1)}$ and especially the lenghty one for $B_n^{(2)}$ are written out in \cref{appendix:operators}.

   We note that the uniform boundedness of $B_n$, $n \in \mathbb{N}$, follows straightforwardly. Furthermore, it can be shown that the sequence $\seq{K}$ is indeed \hyperlink{compactop}{compact}~with the same argumentation as in \cite[Lem.~17]{H23Hdiv}. In particular, we note that $\lim_{n \to \infty} \Vert \tilde{O}_n \Vert_{L(\mathbb{X}_n,L^2)} = 0$, that the operators $M_n$ and $\text{mean}(\cdot)$ give rise to compact terms, and that the construction of $S_n$ allows us to use the compact embedding ${\mathbf H}^1 \hookrightarrow \mathbf{L}^2$. \\[0.8ex]
   \emph{\underline{Step 2:} Uniform coercivity of $B_n^{(1)}$}. 
   First of all, we show that there exists an index $n_0 > 0$ such that $B_n^{(1)}$ is uniformly coercive for all $n > n_0$.

   Let $\mathbf{u}_n \in \mathbb{X}_n$ be arbitrary and $\delta_0, \epsilon_0 \in (0,1)$, $\tau_0 \in (0,\pi/2-\theta)$ be such that the constant $C_{\theta,\tau,\epsilon,\delta}$ defined by \eqref{eq:MonsterConstant} is positive for all $\delta \in (0,\delta_0)$, $\epsilon \in (0,\epsilon_0)$ and $\tau \in (0,\tau_0)$. We recall that this is possible due to \cref{assumption:MachNumber}, as detailed in \cref{rem:MNsmall}. We further recall that by definition of $\theta$, the estimate \eqref{eq:thetaEstimate} holds. 

   Targeting at coercivity of $B_n^{(1)}$ in the sense of \eqref{eq:coercivity:C},
   we set $\xi \coloneqq  e^{-i (\theta + \tau) \text{sgn} \omega}$, $\vert \xi \vert =1$, so that $\operatorname{Re}( \xi (a + i b)) / \cos(\theta + \tau) = a + \text{sgn} (\omega) \tan(\theta + \tau) b$ for $a,b \in \mathbb{R}$. Using \eqref{eq:anI} and \eqref{eq:KnI}, we note that \eqref{eq:anI:3} becomes purely imaginary for $(\mathbf{v}_n',\mathbf{w}_n') = (\mathbf{v}_n,\mathbf{w}_n)$ and obtain
   \begin{align}

     \operatorname{Re} & \left( \xi \langle B_n^{(1)} \mathbf{u}_n, \mathbf{u}_n \rangle_{\mathbb{X}_n} \right) / \cos (\theta + \tau) \nonumber 
      \\
      &\hspace*{-0.35cm}
      = \colorv{\Vert c_s \rho^{1/2} \operatorname{div} \mathbf{v}_{\tau} \Vert^2_{L^2}} - \colorv{\Vert \rho^{1/2} \mathbf{D}_{\mathbf{b}}^n \mathbf{v}_n \Vert^2_{\mathbf{L}^2}} + \colorv{\Vert \mathbf{v}_{\tau} \Vert_{\mathbf{L}^2}} + C_1 \Vert S_n \mathbf{u}_n \Vert_{\mathbf{L}^2}^2 
      \nonumber 


      + \colorw{\Vert c_s \rho^{1/2} M_n \mathbf{w}_n \Vert_{L^2}^2} \hspace*{-2cm}\\ 
      &+ \Vert c_s \rho^{1/2} \tilde{O}_n \mathbf{u}_n \Vert_{L^2}^2 + \colorw{\Vert c_s \rho^{1/2} \pi_n^l P_{L^2_0} \mathbf{q} \cdot \mathbf{w}_\tau \Vert^2_{L^2}} \nonumber 
      + \colorw{\Vert \rho^{1/2} (\omega+i\mathbf{D}_{\mathbf{b}}^n+i\Omega\times) \mathbf{w}_n \Vert^2_{\mathbf{L}^2}} \hspace*{-2cm} \\ 
      &+ \colorvw{2 \tan(\theta+\tau) \text{sgn}(\omega) \operatorname{Im} \left( \langle \rho (\omega+i\mathbf{D}_{\mathbf{b}}^n+i\Omega\times) \mathbf{w}_n, i \mathbf{D}_{\mathbf{b}}^n \mathbf{v}_n \rangle \right)} - \colorw{s_n(\mathbf{w}_n,\mathbf{w}_n)} \hspace*{-2cm}\nonumber \\      
      & + \colorw{\langle \rho \underline{\underline{m}} \mathbf{w}_{\tau}, \mathbf{w}_{\tau} \rangle_{\mathbf{L}^2}}  \nonumber 
      + \colorw{\vert \omega \vert \tan(\theta+\tau)  \Vert (\gamma \rho)^{1/2} \mathbf{w}_{\tau} \Vert_{\mathbf{L}^2}} \geq \dots \nonumber \\
      \intertext{
         Regrouping and applying a weighted Young's inequality ($2ab \leq (1-2\epsilon)^{-1} a^2 + (1-2\epsilon) b^2$)  on the mixed term (involving $\colorw{\mathbf{w}_n}$ and $\colorv{\mathbf{v}_n}$) and using \eqref{eq:thetaEstimate} yields
      }
      &\hspace*{-0.35cm} \dots \!\ge \color{v}\Vert c_s \rho^{1/2} \operatorname{div} \mathbf{v}_{\tau} \Vert^2_{L^2} - \Vert \rho^{1/2} \mathbf{D}_{\mathbf{b}}^n \mathbf{v}_n \Vert^2_{\mathbf{L}^2} (1\!+\!\color{black}\underbrace{ \color{v} \tan^2(\theta\!+\!\tau)(1\!-\!2\epsilon)^{-1}}_{\eqqcolon C_{\theta,\tau,\epsilon}}\color{v}) \!+\! \colorv{\Vert \mathbf{v}_{\tau} \Vert_{\mathbf{L}^2}^2} \!\!\! \nonumber &&\colorv{\text{(I)}}

      \\[-3.5ex] \nonumber
      & + C_1 \Vert S_n \mathbf{u}_n \Vert_{\mathbf{L}^2}^2  &&\text{(II)} \\
      &+ \colorw{\Vert c_s \rho^{1/2} M_n \mathbf{w}_n \Vert_{L^2}^2} + \Vert c_s \rho^{1/2} \tilde{O}_n \mathbf{u}_n \Vert_{L^2}^2 + \colorw{\Vert c_s \rho^{1/2} \pi_n^l P_{L^2_0} \mathbf{q} \cdot \mathbf{w}_{\tau} \Vert^2_{L^2}} && \colorw{\text{(III)}} 
      \nonumber
      \\ 
      & \hspace*{-0.19cm}
      \left.\begin{array}{ll}
            + \colorw{2 \epsilon \Vert \rho^{1/2} (\omega+i\mathbf{D}_{\mathbf{b}}^n+i\Omega\times) \mathbf{w}_n \Vert^2_{\mathbf{L}^2}} \\[0.2cm]
            + \colorw{\vert \omega \vert \left( \tan(\theta + \tau) - \tan(\theta) \right) \Vert (\gamma \rho)^{1/2} \mathbf{w}_{\tau} \Vert_{\mathbf{L}^2} - s_n(\mathbf{w}_n,\mathbf{w}_n)}
        \end{array} \hspace*{1cm}\right\}
        && \colorw{\text{(IV)}} \nonumber

   \end{align}
   $\colorv{\text{(I)}}$ and $\text{(II)}$ allow us to control $\colorv{\mathbf{v}_n}$ while $\colorw{\text{(III)}}$ and $\colorw{\text{(IV)}}$ are responsible for $\colorw{\mathbf{w}_n}$. 
   We start with estimating $\colorv{\text{(I)}}$ from below. Splitting off an $\epsilon$-scaled $\mathbb{X}_n$-norm of $\colorv{\mathbf{v}_n}$ (note that $\colorv{\jnorm{\mathbf{v}_n}{}=0}$), and using \cref{lem:ddiffbEstimate,lem:ddivEstimate} and \eqref{eq:MonsterConstant} for the remainder, we obtain \vspace*{-0.5cm}
   \begin{align*}
      \colorv{\text{(I)}}\! &=\!  \colorv{\epsilon \Vert \mathbf{v}_n \Vert_{\mathbb{X}_n}^2\! \!+\! (1\!-\epsilon) \Vert c_s \rho^{1/2} \!\operatorname{div} \mathbf{v}_{\tau} \Vert^2_{L^2}}


      \colorv{- (1 \!+\! C_{\theta,\tau,\epsilon} \!-\! \epsilon) \Vert \rho^{1/2} \mathbf{D}_{\mathbf{b}}^n \mathbf{v}_n \Vert^2_{\mathbf{L}^2}
      \!+\!\!}\overbrace{\color{v}(1\!-\!\epsilon) \Vert \mathbf{v}_{\tau} \!\Vert_{\mathbf{L}^2}^2}^{\geq 0}      
      \!\!\\
      &\ge\! \colorv{\epsilon \Vert \mathbf{v}_n \Vert_{\mathbb{X}_n}^2} + \underbrace{C_{\theta,\tau,\epsilon,\delta}  \vert S_n \mathbf{u}_n \vert^2_{{\mathbf H}^1_{c_s^2 \rho}}}_{\geq 0} + (1-\epsilon) \left(  \langle \check{O}_n \mathbf{u}_n, \mathbf{u}_n \rangle -  C_{\delta} \Vert S_n \mathbf{u}_n \Vert_{\mathbf{L}^2}^2 \right) 
   \end{align*}
   ~\\[-5ex]



   We then have 
   \begin{align*}
      \colorv{\text{(I)}}\!+\!\text{(II)} \ge & \colorv{\epsilon \Vert \mathbf{v}_n \Vert_{\mathbb{X}_n}^2} 

      + \left(C_1 \!-\! (1\!-\!\epsilon)C_{\delta}\right) \! \Vert S_n \mathbf{u}_n \Vert^2_{\mathbf{L}^2}
	  - (1-\epsilon) \Vert \check{O}_n \Vert_{L(\mathbb{X}_n)} \Vert \mathbf{u}_n \Vert_{\mathbb{X}_n}^2.


   \end{align*}
   Furthermore, recalling \eqref{eq:divwnEquals}, i.e. $\colorw{(\operatorname{div}_{\boldsymbol{\nu}}^n + \pi_n^l P_{L^2_0} \mathbf{q} \cdot ) \mathbf{w}_n} = \colorw{-M_n \mathbf{w}_{n}} - \tilde{O}_n \mathbf{u}_n$, we see
  \begin{equation*}
   \begin{aligned}
      \colorw{\text{(III)}} &= \colorw{\Vert c_s \rho^{1/2} M_n \mathbf{w}_{n} \Vert_{L^2}^2 + \Vert c_s \rho^{1/2} \tilde{O}_n \mathbf{u}_n \Vert_{L^2}^2 + \Vert c_s \rho^{1/2} \pi_n^l P_{L^2_0} \mathbf{q} \cdot \mathbf{w}_{\tau} \Vert_{L^2}^2}
       \\
      &
      \ge \frac14 \colorw{\Vert c_s \rho^{1/2} \operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{w}_n \Vert_{\mathcal{T}_n}^2}.
   \end{aligned}
  \end{equation*}
  For the first term in $\colorw{\text{(IV)}}$ we 
  obtain from a weighted Young's inequality (as in \cite{HH21})
$$
\colorw{2 \epsilon \Vert \rho^{1/2} (\omega+i\mathbf{D}_{\mathbf{b}}^n+i\Omega\times) \mathbf{w}_n \Vert^2_{\mathbf{L}^2}}
\geq 
\colorw{\epsilon \Vert \rho^{1/2} \mathbf{D}_{\mathbf{b}}^n \mathbf{w}_n \Vert^2_{\mathbf{L}^2}} - \colorw{C \epsilon
\Vert \rho^{1/2} \mathbf{w}_\tau \Vert^2_{\mathbf{L}^2}}
$$
for $C\in\mathbb{R}$ only depending on $\omega$ and $\Omega$. For sufficiently small $\epsilon$ we can dominate the latter part by the second line of $\colorw{\text{(IV)}}$. Exploiting $\colorw{-s_n(\mathbf{w}_n,\mathbf{w}_n) \geq  \alpha \jnorm{\mathbf{w}_n}{2}}$ and choosing $\epsilon$ small enough (compared to $\alpha$, $\frac14$ and especially $\tau$), we get control of the $\mathbb{X}_n$-norm of $\colorw{\mathbf{v}_n}$:
$$
\colorw{\text{(III)}} + \colorw{\text{(IV)}} \geq \epsilon \colorw{\Vert \mathbf{w}_n \Vert^2_{\mathbb{X}_n}}.
$$

Combining all estimates and $\Vert \mathbf{u}_n \Vert_{\mathbb{X}_n}^2 \leq 2 \Vert \mathbf{v}_n \Vert_{\mathbb{X}_n}^2 + 2 \Vert \mathbf{w}_n \Vert_{\mathbb{X}_n}^2$, we obtain 

  \begin{equation*}
   \begin{aligned}
      &\operatorname{Re} \left( \xi \langle B_n^{(1)} \mathbf{u}_n, \mathbf{u}_n \rangle_{\mathbb{X}_n} \right) / \cos(\theta + \tau)\ge \colorv{\text{(I)}} + \text{(II)} + \colorw{\text{(III)}} + \colorw{\text{(IV)}} \\
      &\ge \frac{\epsilon}{2} \Vert \mathbf{u}_n \Vert^2_{\mathbb{X}_n} + \left( C_1 - (1-\epsilon)C_{\delta} \right) \Vert S_n \mathbf{u}_n \Vert^2_{\mathbf{L}^2} - (1-\epsilon) \Vert \check{O}_n \Vert_{L(\mathbb{X}_n)} \Vert \mathbf{u}_n \Vert_{\mathbb{X}_n}^2.
   \end{aligned}
  \end{equation*}
  Since $\lim_{n \to \infty} \Vert \check{O}_n \Vert_{L(\mathbb{X}_n)} = 0$, we can choose $n_1 > n_0$ large enough such that $(1-\epsilon) \Vert \check{O}_n \Vert_{L(\mathbb{X}_n)} < \epsilon/4$ and thus with $C_1 > (1-\epsilon)C_{\delta}$
  \begin{equation*}
   \begin{aligned}
      \operatorname{Re} \left( \xi \langle B_n^{(1)} \mathbf{u}_n, \mathbf{u}_n \rangle_{\mathbb{X}_n} \right)  / \cos(\theta + \tau)
      \ge \frac{\epsilon}{4} \Vert \mathbf{u}_n \Vert^2_{\mathbb{X}_n} 
   \end{aligned}
  \end{equation*}
  for $n > n_1$. 




  Thus, $B_n^{(1)}$ is uniformly coercive (in the sense of \eqref{eq:coercivity:C}) for all $n > n_1$. \\[0.8ex]
  \emph{\underline{Step 3:} Uniform coercivity of $B_n$}. We have shown that $B_n^{(1)}$ is uniformly coercive in \emph{Step 2}, so it remains to show that $B_n$ (after addition of $B_n^{(2)}$) is uniformly coercive as well.
  To this end, we want to derive a bound for $B_n^{(2)}$ of the form
  \begin{align}
   \operatorname{Re} ( \xi \langle B_n^{(2)} \mathbf{u}_n, \!\mathbf{u}_n \rangle_{\mathbb{X}_n}) /\! \cos(\theta + \tau) \!\ge\! -(\epsilon/8 \!+\! \zeta_{1,n}) \Vert \mathbf{u}_n \Vert^2_{\mathbb{X}_n} \!+ (C_2 \!-  \zeta_2) \vert \mathbf{u}_n \vert_{K_n^{(2)}}^2 \!
   \label{BnII:lowerbound}
  \end{align}
  for $(\zeta_{1,n})_{n\in \mathbb{N}}$ and $\zeta_{1,n}, \zeta_2 \in \mathbb{R}_+$ with the semi-norm 
  \begin{align*}
   \vert \mathbf{u}_n \vert_{K_n^{(2)}}^2 & \! \! \coloneqq  \! \colorv{\Vert \mathbf{v}_{\tau} \Vert^2_{\mathbf{L}^2}}   \! \! + \! \Vert S_n \mathbf{u}_n \Vert^2_{\mathbf{L}^2}  \!+ \! \Vert c_s \rho^{1/2} \tilde{O}_n \mathbf{u}_n \Vert^2_{L^2}  \!+ \! \colorw{\Vert c_s \rho^{1/2} M_n  \! \mathbf{w}_{n} \Vert^2_{L^2}}  \!+ \! \colorw{\Vert \text{mean}(\mathbf{q}  \! \cdot  \! \mathbf{w}_{\tau}) \Vert^2_{L^2}} \\
   &= C_2^{-1} K_n^{(2)}(\mathbf{u}_n,\mathbf{u}_n).
  \end{align*}
  We will show that $\zeta_{1,n} \to 0$ for $n \to \infty$ so that $- (\epsilon/8 + \zeta_{1,n})  \Vert \mathbf{u}_n \Vert^2_{\mathbb{X}_n}$ can be dominated by the $B_n^{(1)}$-contribution for sufficiently large $n$. The bound \eqref{BnII:lowerbound} allows us to choose $C_2$ sufficiently large to compensate for the $- \zeta_2 \vert \mathbf{u}_n \vert_{K_n^{(2)}}^2$ term and obtain the uniform coercivity of $B_n$.

  To prove \eqref{BnII:lowerbound}, it suffices to show the boundedness of $a_n^{(2)}$ in the following form
  \begin{align}
   | \langle a_n^{(2)} \mathbf{u}_n, \mathbf{u}_n \rangle_{\mathbb{X}_n} | \le \eta_{1,n} \Vert \mathbf{u}_n \Vert^2_{\mathbb{X}_n} + \eta_2 \Vert \mathbf{u}_n \Vert_{\mathbb{X}_n} \vert \mathbf{u}_n \vert_{K_n^{(2)}}. 
   \label{eq:anII:upperbound:I}
   \intertext{
      for $(\eta_{1,n})_{n \in \mathbb{N}} \to 0$ for $n \to \infty$ and $\eta_2$ bounded. Then, a weighted Young's inequality of the form $\eta_2 a b \leq \frac12 \frac{\epsilon}{4 \cos(\theta+\tau)} a^2 + \frac12 \frac{4 \cos(\theta+\tau) \eta_2^2}{\epsilon} b^2$ yields 
   }
      | \langle a_n^{(2)} \mathbf{u}_n, \mathbf{u}_n \rangle_{\mathbb{X}_n} | \le \frac{\epsilon/8 + \zeta_{1,n}}{\cos(\theta+\tau)} \Vert \mathbf{u}_n \Vert^2_{\mathbb{X}_n} + 
      \frac{\zeta_2}{\cos(\theta+\tau)} \vert \mathbf{u}_n \vert_{K_n^{(2)}}^2. 
      \label{eq:anII:upperbound}
      \end{align}
   with $\zeta_{1,n} = \eta_{1,n} \cos(\theta+\tau)$ and $\zeta_2 = 2/\epsilon \cos^2(\theta + \tau) \eta_2^2$ which implies \eqref{BnII:lowerbound}.
   It hence remains to show \eqref{eq:anII:upperbound:I}.

   $a_n^{(2)}(\cdot,\cdot)$ effectively contains all the terms of $a_n(\cdot,\cdot)$ that are not considered in $a_n^{(1)}(\cdot,\cdot)$. 
   Most terms are of the form that they pair a term that can be bounded by $\vert \cdot \vert_{K_n^{(2)}}$ with another term that can be bounded by $\vert \cdot \vert_{\mathbb{X}_n}$. Those terms are thence directly suitable for \eqref{eq:anII:upperbound} and in the following, we only discuss the terms that do not match this pattern; for completeness we state the full expression $a_n^{(2)}(\cdot,\cdot)$ in \cref{appendix:operators}.

   The terms  of \eqref{eq:anII:upperbound} that do not match the pattern described above stem from contributions of $\colorw{\operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{w}_n + \mathbf{q} \cdot \mathbf{w}_n}$. 
   We then shift in $\colorw{\pi_n^l P_{L^2_0} (\mathbf{q} \cdot \mathbf{w}_n)}$, cf.~\eqref{eq:adiv:2}, and make use of \eqref{eq:divwnEquals} to bound $\colorw{\operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{w}_n + \pi_n^l P_{L^2_0} \mathbf{q} \cdot \mathbf{w}_n}$ by $\vert \mathbf{u}_n \vert_{K_n^{(2)}}$. 
   The remaining terms are then of the form 
   $\langle \colorw{c_s^2 \rho (\mathrm{id} - \pi_n^l  P_{L^2_0} ) (\mathbf{q} \cdot \mathbf{w}_{\tau})}, \operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{z}_n \rangle$ for $\mathbf{z}_n \in \{\colorv{\mathbf{v}_n'}, \colorw{\mathbf{w}_n'}\}$.
   To exploit the approximation properties of $\pi_n^l$ here, we first shift in another $\text{mean} (\mathbf{q} \cdot \mathbf{w}_n)$ term (which is itself bounded by constant times $\Vert \mathbf{u}_n \Vert_{K_n^{(2)}}$) and only have to deal with the following expression where we abbreviate $\Pi^\ast = \mathrm{id} - \text{mean} - \pi_n^l  P_{L^2_0}$: 
   \begin{align*}
   &\vert \langle \colorw{c_s^2 \rho \Pi^\ast (\mathbf{q} \cdot \mathbf{w}_{\tau})}, \operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{z}_n \rangle \vert
   = \vert \langle \colorw{\mathbf{q} \cdot \mathbf{w}_{\tau}}, \Pi^\ast (c_s^2 \rho \operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{z}_n) \rangle \vert \\
   &\le \Vert \mathbf{q} \Vert_{\mathbf{L}^\infty} \colorw{\Vert \mathbf{w}_\tau \Vert_{\mathbf{L}^2}} \Vert \Pi^\ast (c_s^2 \rho \operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{z}_n) \Vert_{L^2} \lesssim \Vert \mathbf{u}_n \Vert_{\mathbb{X}_n} \Vert \Pi^\ast (c_s^2 \rho \operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{z}_n) \Vert_{L^2}, 
  \end{align*}
  We estimate the last term using a discrete commutator technique \cite{B99} to obtain
  \begin{align*}
   \Vert & \Pi^\ast (c_s^2 \rho  \operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{z}_n )\Vert_{L^2}^2 \!=\!\! \sum_{\tau \in \mathcal{T}_n} \Vert \Pi^\ast (c_s^2 \rho \operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{z}_n) \Vert^2_{L^2(\tau)}
   \!=\!\! \sum_{\tau \in \mathcal{T}_n} \Vert \Pi^\ast ((c_s^2 \rho \!-\! c_{\tau}) \operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{z}_n) \Vert^2_{L^2(\tau)} \\

   & \le \sum_{\tau \in \mathcal{T}_n} \Vert c_s^2 \rho - c_{\tau} \Vert_{L^\infty(\tau)}^2 \Vert \operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{z}_n \Vert_{L^2(\tau)}^2 
   \le (C^L_{c_s^2 \rho})^2 h_n^2 \Vert \mathbf{z}_n \Vert^2_{\mathbb{X}_n} \lesssim h_n^2 \Vert \mathbf{u}_n \Vert^2_{\mathbb{X}_n}.
  \end{align*}
  Here, we used that $\Pi^\ast r = 0$ for any piecewise polynomial $r$ of degree $k-1$
  and hence $\Pi^\ast c_\tau \operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{z}_n = 0$ for any piecewise constant $c_\tau$.

  This reveals that all terms in $a_n^{(2)}$ are suitable for \eqref{eq:anII:upperbound:I} and hence \eqref{BnII:lowerbound} holds. 
  Together with  \emph{Step 2}, $C_2$ and $n$ sufficiently large we hence obtain 
  \begin{align}
   \operatorname{Re} ( \xi \langle B_n \mathbf{u}_n, \!\mathbf{u}_n \rangle_{\mathbb{X}_n}) \!\ge\! 3\epsilon/16 \cos(\theta + \tau) \Vert \mathbf{u}_n \Vert^2_{\mathbb{X}_n} 
   \label{Bn:coercive}.
  \end{align}











  \emph{\underline{Step 4:} Asymptotic consistency of $B_n$}. In the last step,  we want to show that there exists a bijective operator $B \in L(\mathbb{X})$ such that $B_n$ \hyperlink{approximate}{approximates}~$B$. 

  For $\mathbf{u}, \mathbf{u}' \in \mathbb{X}$, we define
   \begin{subequations}\label{eq:K}
      \begin{align}
         \langle K \mathbf{u}, \mathbf{u}' \rangle_{\mathbb{X}} \coloneqq &-(1+C_2) \colorv{\langle \mathbf{v}, \mathbf{v}' \rangle} - (C_1 + C_2) \colorv{\langle \mathbf{v}, \mathbf{v}' \rangle} \label{eq:K:a} \tag{$K$-a} \\
         &- (1+C_2) \colorw{\langle c_s^2 \rho M \mathbf{w}, M \mathbf{w}' \rangle} - C_2 \colorw{\langle \text{mean}(\mathbf{q} \cdot \mathbf{w}), \text{mean}(\mathbf{q} \cdot \mathbf{w}') \label{eq:K:b} \tag{$K$-b} \rangle}
      \end{align}
   \end{subequations}
   and set $B \coloneqq AT - K$. Since $M$ is of finite rank and $\mathbf{v} = P_V \mathbf{u} \in {\mathbf H}^1$, the compactness of the operator $K$ follows from the compact embedding ${\mathbf H}^1 \hookrightarrow \mathbf{L}^2$. Rewriting the operator $B$ with similar arguments as in \emph{Step 1}, cf.~\eqref{eq:B}, we can show that $B$ is coercive using the same arguments as in \emph{Step 2} and \emph{Step 3}. Thus, $B$ is bijective. It remains to show that $B_n$ \hyperlink{approximate}{approximates}~$B$, that is $\lim_{n \to \infty} \Vert (B_n p_n - p_n B) \mathbf{u} \Vert_{\mathbb{X}_n} = 0$. 

   To this end, we note that it suffices to show that $K_n$ \hyperlink{approximate}{approximates}~$K$, since we can use that $B_n = A_n T_n - K_n$, $B = AT-K$ and estimate 
   \begin{align*}
      \Vert &(B_n p_n - p_n B) \mathbf{u} \Vert_{\mathbb{X}_n} \le \Vert (K_n p_n - p_n K) \mathbf{u} \Vert_{\mathbb{X}_n} + \Vert (A_n T_n p_n - p_n A T ) \mathbf{u} \Vert_{\mathbb{X}_n} \\
      &\le \Vert (K_n p_n - p_n K) \mathbf{u} \Vert_{\mathbb{X}_n} + \Vert (A_n p_n - p_n A) T \mathbf{u} \Vert_{\mathbb{X}_n} 

      + \Vert A_n \Vert_{L(\mathbb{X}_n)} \Vert (T_n p_n - p_n T)  \mathbf{u} \Vert_{\mathbb{X}}.
   \end{align*}
   By \cref{thm:AnToA} and \cref{lem:TnToT}, $A_n$ \hyperlink{approximate}{approximates}~$A$ and $T_n$ \hyperlink{approximate}{approximates}~$T$ so the last two terms converge to zero. Thus, it indeed suffices to show that $K_n$ \hyperlink{approximate}{approximates}~$K$ to conclude that $B_n$ \hyperlink{approximate}{approximates}~$B$. 

   Similar to the proof of \cref{thm:AnToA}, we choose $\mathbf{u}_n ' \in \mathbb{X}_n$, $n \in \mathbb{N}$, $\Vert \mathbf{u}_n' \Vert_{\mathbb{X}_n} = 1$, such that $\Vert (K_n p_n - p_n K) \mathbf{u} \Vert_{\mathbb{X}_n} \le \vert \langle (K_n p_n - p_n K) \mathbf{u}, \mathbf{u}_n' \rangle_{\mathbb{X}_n} \vert + 1/n$. For an arbitrary subsequence $\mathbb{N}' \subset \mathbb{N}$, we can choose $\mathbf{u}' \in \mathbb{X}$ and a subsequence $\mathbb{N}'' \subset \mathbb{N}$ such that $\mathbf{u}_n' \overset{\mathbf{L}^2}{\rightharpoonup} \mathbf{u}'$, $c_s^2 \rho \operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{u}_n' \overset{L^2}{\rightharpoonup} c_s^2 \rho \operatorname{div} \mathbf{u}'$ and $\rho \mathbf{D}_{\mathbf{b}}^n \mathbf{u}_n' \overset{\mathbf{L}^2}{\rightharpoonup} \rho \partial_{\mathbf{b}} \mathbf{u}'$ due to \cref{lem:weakConvergence}. 

   We compute that 
   \begin{align*}
      \inner{p_n K \mathbf{u}, \mathbf{u}_n'}_{\mathbb{X}_n} \overset{\eqref{eq:def:pn}}&{=} \inner{\operatorname{div} K \mathbf{u}, c_s^2 \rho \operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{u}_n'} + \inner{K \mathbf{u}, \mathbf{u}_n'} + \inner{\partial_{\mathbf{b}} K \mathbf{u}, \rho \mathbf{D}_{\mathbf{b}}^n \mathbf{u}_n'}\\
      \overset{n \in \mathbb{N}''}&{\to} \innercsr{\operatorname{div} K \mathbf{u}, \mathbf{u}'} + \inner{K \mathbf{u}, \mathbf{u}'} + \innerr{\partial_{\mathbf{b}} K \mathbf{u}, \partial_{\mathbf{b}} \mathbf{u}'} = \inner{K \mathbf{u}, \mathbf{u}'}_{\mathbb{X}}.
   \end{align*}


   Thus, we have to show that $\lim_{n \in \mathbb{N}''} \langle K_n p_n \mathbf{u}, \mathbf{u}_n' \rangle_{\mathbb{X}_n} = - \langle K \mathbf{u}, \mathbf{u}' \rangle_{\mathbb{X}}$. We recall that $K_n \coloneqq - K_n^{(1)} - K_n^{(2)}$ and therefore
   \begin{subequations}
      \begin{align}
         \inner{K_n p_n &\mathbf{u}, \mathbf{u}_n'}_{\mathbb{X}_n}\nonumber \\
         =  &-(1 + C_2) \inner{(\colorv{P_{V_n} p_n \mathbf{u}})_{\tau},\mathbf{v}_{\tau}'} - (C_1 + C_2) \inner{S_n p_n \mathbf{u}, S_n \mathbf{u}_n'} \label{eq:Knpnu:a} \tag{$K_n$-a} \\
         &-(1 + C_2) \inner{c_s^2 \rho \tilde{O}_n p_n \mathbf{u}, \tilde{O}_n \mathbf{u}_n'} - (1 + C_2) \inner{c_s^2 \rho M_n (\mathrm{id}_{\mathbb{X}_n} - P_{V_n}) p_n \mathbf{u}, \colorw{\mathbf{w}_{n}'}} \label{eq:Knpnu:b} \tag{$K_n$-b} \\
         &-(1 + C_2) \inner{\text{mean}(\mathbf{q} \cdot (\mathrm{id}_{\mathbb{X}_n} - P_{V_n})\PVol{p_n \mathbf{u}}), \colorw{\text{mean}(\mathbf{q} \cdot \mathbf{w}_{\tau}')}}. \label{eq:Knpnu:c} \tag{$K_n$-c}
       \end{align}
   \end{subequations} 
   In the following, we show that \eqref{eq:Knpnu:a} converges to $\eqref{eq:K:a}$ and $\eqref{eq:Knpnu:b} + \eqref{eq:Knpnu:c}$ converges to $\eqref{eq:K:b}$.


   \emph{Step 4a: Convergence of \eqref{eq:Knpnu:a}.} To show that $\eqref{eq:Knpnu:a}$ converges to $\eqref{eq:K:a}$, we exploit the convergence of $p_n \mathbf{u}$.
   Using the approximation properties of $\pi_n^d$ and the same argumentation as in \cref{lem:TnToT}, cf. especially \eqref{eq:PVSnpn:conv}, we have
   \begin{align*}
         \vert &\colorv{\langle \mathbf{v}, \mathbf{v}_{\tau}' \rangle} - \langle \PVol{P_{V_n} p_n \mathbf{u}}, \colorv{\mathbf{v}_{\tau}'} \rangle \vert = \vert (\langle P_{V} - \pi_n^d S_n p_n) \mathbf{u}, \colorv{\mathbf{v}_{\tau}'} \rangle \vert  \\
         &\lesssim \vert \langle (P_V - \pi_n^d P_{V}) \mathbf{u}, \colorv{\mathbf{v}_{\tau}'} \rangle \vert  + \vert \langle \pi_n^d (P_{V} - S_n p_n )\mathbf{u}, \colorv{\mathbf{v}_{\tau}'}\rangle \vert \\
         &\lesssim h_{n} \Vert P_V \mathbf{u} \Vert_{{\mathbf H}^1} + d_n(\mathbf{u},p_n \mathbf{u}) + \Vert (\mathrm{id}_{L^2_0} - \pi_n^l) P_{L^2_0} \mathbf{q} \cdot \mathbf{u} \Vert_{L^2} \overset{n \in \mathbb{N}''}{\to} 0, \\
      \text{and  }~ \vert &\langle \colorv{\mathbf{v}}, S_n \mathbf{u}_n' \rangle - \langle S_n p_n \mathbf{u}, S_n \mathbf{u}_n' \rangle \vert \!=\! \vert \langle (P_V - S_n p_n) \mathbf{u}, S_n \mathbf{u}_n' \rangle \vert 
      \\
      &\!\lesssim\! \Vert (P_{V} - S_n p_n) \mathbf{u} \Vert_{\mathbf{L}^2} 
      \lesssim d_n(\mathbf{u},p_n \mathbf{u}) + \Vert ( \mathrm{id}_{L^2_0} - \pi_n^l) P_{L^2_0} \mathbf{q} \cdot \mathbf{u} \Vert_{L^2}  \overset{n \in \mathbb{N}''}{\to} 0,
   \end{align*}
   where we used \cref{lem:dnpnuToZero} and the pointwise convergence of $\pi_n^l$ to $\mathrm{id}_{L^2_0}$. Hence,
   \begin{equation*}
      \lim_{n \in \mathbb{N}''} \eqref{eq:Knpnu:a} = \lim_{n \in \mathbb{N}''} \left( -(1 + C_2) \colorv{\inner{\mathbf{v}, \mathbf{v}_{\tau}'}} - (C_1 + C_2) \inner{\colorv{\mathbf{v}},S_n \mathbf{u}_n'} \right).
   \end{equation*}
   It remains to show that the right-hand side converges to $\eqref{eq:K:a}$, i.e. 
   $\inner{\colorv{\mathbf{v}},S_n \mathbf{u}_n'} \overset{n \in \mathbb{N}''}{\to} \colorv{\inner{\mathbf{v},\mathbf{v}'}}$. Let $S := \nabla ( (\operatorname{div} + P_{L^2_0}\mathbf{q} \cdot + M) \nabla)^{-1}$ such that
   \begin{align*}
      \langle &\colorv{\mathbf{v}}, S_n \mathbf{u}_n' \rangle - \colorv{\langle \mathbf{v}, \mathbf{v}' \rangle}=  \langle \colorv{\mathbf{v}}, S_n \mathbf{u}_n' - P_V \mathbf{u}' \rangle \\
      &\!=\!  \langle \colorv{\mathbf{v}}, S ((\operatorname{div}_{\boldsymbol{\nu}}^n + \pi_n^l P_{L^2_0} \mathbf{q} \cdot \! + M_n) \mathbf{u}_n' - ( \operatorname{div} + P_{L^2_0} \mathbf{q} \cdot \! + M ) \mathbf{u}') \rangle \\
      &\!=\!  \langle S^\ast \colorv{\mathbf{v}}, \operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{u}_n' \!-\! \operatorname{div} \mathbf{u}' \rangle \!+\! \langle S^\ast \colorv{\mathbf{v}}, \pi_n^l P_{L^2_0} \mathbf{q} \cdot \PVol{\mathbf{u}_n'} \!-\! P_{L^2_0} \mathbf{q} \cdot \mathbf{u}' \rangle 

      \!+\! \langle S^\ast \colorv{\mathbf{v}}, M_n \mathbf{u}_n' \!-\! M \mathbf{u}' \rangle.
   \end{align*}
   By choice of the subsequence $\mathbb{N}'' \subset \mathbb{N}$ and \cref{lem:weakConvergence}, we have that $c_s^2 \rho \operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{u}_n' \overset{L^2}{\rightharpoonup} c_s^2 \rho \operatorname{div} \mathbf{u}'$ (and hence $\operatorname{div}_{\boldsymbol{\nu}}^n \mathbf{u}_n' \overset{L^2}{\rightharpoonup} \operatorname{div} \mathbf{u}'$) and therefore $M_n \mathbf{u}_n' \to M \mathbf{u}'$ by construction of $M_n$ and $M$. Therefore, the first and the last term converge to zero as $S^\ast \colorv{\mathbf{v}} \in L^2$. 
   Furthermore, we have that 
   \begin{equation*}
      \begin{aligned}
         &\langle S^\ast \colorv{\mathbf{v}}, \pi_n^l P_{L^2_0} \mathbf{q} \cdot \PVol{\mathbf{u}_n'} - P_{L^2_0} \mathbf{q} \cdot \mathbf{u}' \rangle \\
         = &\langle S^\ast \colorv{\mathbf{v}}, (\pi_n^l - \operatorname{id}) P_{L^2_0} \mathbf{q} \cdot \mathbf{u} \rangle + \langle S^\ast \colorv{\mathbf{v}}, \pi_n^l P_{L^2_0} \mathbf{q} \cdot (\PVol{\mathbf{u}_n'} - \mathbf{u}') \rangle \\
      \end{aligned}
   \end{equation*} 
   The first term converges to zero due to the pointwise convergence of $\pi_n^l$ to $\mathrm{id}$. For the second term, we first notice that $\pi_n^l$ is uniformly bounded and by \cref{lem:weakConvergence} $\PVol{\mathbf{u}_n'} \overset{\mathbf{L}^2}{\rightharpoonup} \mathbf{u}'$. Therefore $P_{L^2_0} \mathbf{q} \cdot \mathbf{u}_n' \overset{\mathbf{L}^2}{\rightharpoonup} P_{L^2_0} \mathbf{q} \cdot \mathbf{u}'$ because the compact operator $P_{L^2_0} \mathbf{q} \cdot$ maps weakly convergent sequences onto weakly convergent sequences. We conclude $\inner{\colorv{\mathbf{v}},S_n \mathbf{u}_n'} \overset{n \in \mathbb{N}''}{\to} \colorv{\inner{\mathbf{v},\mathbf{v}'}}$ and hence $\lim_{n \in \mathbb{N}''} \eqref{eq:Knpnu:a} = \eqref{eq:K:a}$. 

   \emph{Step 4b: Convergence of \eqref{eq:Knpnu:b} \& \eqref{eq:Knpnu:c} to \eqref{eq:K:b}.}
   For \eqref{eq:Knpnu:b}, we first note that $\lim_{n \to \infty} \Vert \tilde{O}_n \Vert_{L(\mathbb{X}_n,L^2_0)} = 0$ due to the arguments in \cref{lem:PvIdempotent} so that we only have to consider the second term. 
   With similar arguments as in the proof of \cref{lem:TnToT} we have (recall that $\colorw{\mathbf{w}} = (\mathrm{id} - P_{V})\mathbf{u}$)
   \begin{align*}
      \vert &\colorw{\langle M \mathbf{w}, M_n \mathbf{w}_{n}' \rangle} - \langle M_n (\mathrm{id} - P_{V_n})(p_n \mathbf{u}), M_n \colorw{\mathbf{w}_{n}'} \rangle \vert \\
      &\lesssim \Vert \operatorname{div} (\mathbf{u} - P_V \mathbf{u}) - \operatorname{div}_{\boldsymbol{\nu}}^n (p_n \mathbf{u} - P_{V_n} p_n \mathbf{u}) \Vert_{L^2} \lesssim d_n(\mathbf{u},p_n \mathbf{u}) + d_n(P_V \mathbf{u}, P_{V_n} p_n \mathbf{u}), 
   \end{align*}
   where the first term converges to zero due to \cref{lem:dnpnuToZero} and the second term converges to zero with the same argumentation as in the proof of \cref{lem:TnToT}, cf.~\eqref{eq:PVuPVnpnuToZero}. Applying \cref{lem:weakConvergence} yields $\lim_{n \in \mathbb{N}''} \eqref{eq:Knpnu:b} = \lim_{n \in \mathbb{N}''} (1 + C_2) \colorw{\inner{M \mathbf{w}, M_n \mathbf{w}_n'}} = (1 + C_2) \colorw{\inner{M \mathbf{w}, M \mathbf{w}'}}$.

   Finally, we consider \eqref{eq:Knpnu:c} and calculate that
   \begin{align*}
      \vert &\colorw{\langle \text{mean} (\mathbf{q} \cdot \mathbf{w}), \text{mean}(\mathbf{q} \cdot \mathbf{w}_{\tau}') \rangle} - \langle \text{mean} (\mathbf{q} \cdot \PVol{(\mathrm{id}-P_{V_n})(p_n \mathbf{u})}), \colorw{\text{mean}(\mathbf{q} \cdot \mathbf{w}_{\tau}')} \rangle \vert \\
      &\lesssim \Vert \mathbf{u} - P_{V} \mathbf{u} - \PVol{p_n \mathbf{u} - P_{V_n} p_n \mathbf{u}} \Vert_{\mathbf{L}^2} \\
      &\lesssim \Vert p_n P_V \mathbf{u} - \PVol{ P_{V_n} p_n \mathbf{u}} \Vert_{\mathbf{L}^2} + d_n(\mathbf{u},p_n \mathbf{u}) + d_n (P_V \mathbf{u}, p_n P_{V_n} \mathbf{u}) \overset{n \in \mathbb{N}''}{\to} 0, 
   \end{align*}
   where we again apply \cref{lem:dnpnuToZero} and \cref{lem:TnToT}.

   Altogether, we obtain that $\lim_{n \in \mathbb{N}''} \eqref{eq:Knpnu:a} = \eqref{eq:K:a}$ and $\lim_{n \in \mathbb{N}''} (\eqref{eq:Knpnu:b} + \eqref{eq:Knpnu:c}) = \eqref{eq:K:b}$ and thus $K_n$ \hyperlink{approximate}{approximates}~$K$. Due to the argumentation above, we conclude that $B_n$ \hyperlink{approximate}{approximates}~$B$ which finishes the proof.

   To summarize, in \emph{Step 1} we have defined the decomposition $A_n T_n = B_n + K_n$, where the sequence $\seq{K}$ is compact. In \emph{Step 2} and \emph{Step 3}, we have shown that the sequence $\seq{B}$ is uniformly coercive and therefore \hyperlink{stable}{stable}. Finally, in \emph{Step 4}, we have shown that there exists a bijective operator $B \in L(\mathbb{X})$ such that $B_n$ \hyperlink{approximate}{approximates}~B.

\begin{equation}\label{eq:adiv:1}
      \begin{aligned}
         \hspace*{-2cm}a_n^{(\operatorname{div} + \mathbf{q} \cdot)}&(T_n \mathbf{u}_n,\mathbf{u}_n') =  
         \inner{c_s^2 \rho (\operatorname{div}_{\boldsymbol{\nu}}^n + \mathbf{q} \cdot) 
         \mathbf{u}_n,

         (\operatorname{div}_{\boldsymbol{\nu}}^n + \mathbf{q} \cdot) 

         \mathbf{u}_n'
         } 
         = 
